//! Port module (navigation, round 2): road_query_random_lane_setup 0xA8A4F0, nav_tri_edge_midpoint
//! 0xA103B0, nav_cells_heuristic 0xA11750 and the other ports listed in `install()`. Callees stay the
//! original game functions, called by address with the registers and stack arguments the LTCG build
//! sets up; every comparison keeps the original's polarity (x87 compares are decoded below).
//!
//! The originals are x87: every `fld dword` / `fstp dword` pair is an f64 operation with an `as f32` at
//! the store (the game runs the x87 at 53-bit precision, so f64 arithmetic is bit-exact).
//!
//! Checks (per port, see `install()` and the notes at each function):
//! - pure functions: relocated-original shadow for the first `SHADOW_CALLS` calls, the original's result
//!   wins on a mismatch;
//! - writers with known writes: snapshot shadow;
//! - functions that write too much or whose callees have side effects: per-branch counters only.
//! After the shadow window every port is the bare Rust body.
//!
//! Offline: `mod tests` (bottom) runs the original bytes (relocated, their calls aimed at recording
//! stubs or test copies, their globals moved by `DELTA`) against the real thunk on random worlds.

#![allow(unused_imports, dead_code, unsafe_op_in_unsafe_fn)]

use std::sync::atomic::{AtomicU32, AtomicUsize, Ordering};

use crate::portlib::*;
use crate::{detour, log};

const SHADOW_CALLS: u32 = 3000;

// The offline differential test keeps the game's globals (0xD00000..0x350000) at a fixed offset,
// because their addresses are taken in a test process; the Rust ports read through these shadows
// there. Pointers to the test's objects lie outside that range. The production build uses portlib.
#[cfg(test)]
pub(crate) use crate::port_frame2::{DELTA, tr};
#[cfg(test)]
unsafe fn rd(p: usize) -> u32 {
    unsafe { *(tr(p) as *const u32) }
}
#[cfg(test)]
unsafe fn rb(p: usize) -> u8 {
    unsafe { *(tr(p) as *const u8) }
}
#[cfg(test)]
unsafe fn rf(p: usize) -> f32 {
    unsafe { *(tr(p) as *const f32) }
}
#[cfg(test)]
unsafe fn wd(p: usize, v: u32) {
    unsafe { *(tr(p) as *mut u32) = v }
}
#[cfg(test)]
unsafe fn wb(p: usize, v: u8) {
    unsafe { *(tr(p) as *mut u8) = v }
}
#[cfg(test)]
unsafe fn ww(p: usize, v: u16) {
    unsafe { *(tr(p) as *mut u16) = v }
}
#[cfg(not(test))]
unsafe fn ww(p: usize, v: u16) {
    unsafe { *(p as *mut u16) = v }
}
/// A 16-bit load, zero-extended.
#[cfg(test)]
unsafe fn rw(p: usize) -> u32 {
    unsafe { *(tr(p) as *const u16) as u32 }
}
#[cfg(not(test))]
unsafe fn rw(p: usize) -> u32 {
    unsafe { *(p as *const u16) as u32 }
}
/// Every call into the rest of the game goes through a recording stub in the test.
#[cfg(test)]
unsafe fn call_regs(f: usize, eax: u32, ecx: u32, edx: u32, esi: u32, edi: u32, args: &[u32]) -> u32 {
    unsafe { crate::portlib::call_regs(dt::redirect(f), eax, ecx, edx, esi, edi, args) }
}
#[cfg(test)]
fn tgt(a: usize) -> usize {
    dt::redirect(a)
}
#[cfg(not(test))]
#[inline(always)]
fn tgt(a: usize) -> usize {
    a
}
/// An absolute game address passed to a callee as a value.
#[cfg(test)]
fn ga(p: usize) -> u32 {
    tr(p) as u32
}
#[cfg(not(test))]
fn ga(p: usize) -> u32 {
    p as u32
}

/// Call a game function that returns on ST0 (popped), the value unrounded.
unsafe fn call_st0(f: usize, eax: u32, ecx: u32, edx: u32, esi: u32, edi: u32, args: &[u32]) -> f64 {
    let f = tgt(f);
    let mut out = 0f64;
    let block: [u32; 9] = [f as u32, ecx, edx, esi, edi, args.as_ptr() as u32, args.len() as u32, eax, &mut out as *mut f64 as u32];
    unsafe {
        std::arch::asm!(
            "push ebx", "push esi", "push edi", "push ebp",
            "mov ebp, esp",
            "mov ebx, eax",
            "mov ecx, [ebx + 24]",
            "mov esi, [ebx + 20]",
            "2:",
            "test ecx, ecx",
            "jz 3f",
            "push dword ptr [esi + ecx*4 - 4]",
            "dec ecx",
            "jmp 2b",
            "3:",
            "mov ecx, [ebx + 4]", "mov edx, [ebx + 8]", "mov esi, [ebx + 12]", "mov edi, [ebx + 16]",
            "mov eax, [ebx + 28]",
            "call dword ptr [ebx]",
            "mov ecx, [ebx + 32]",
            "fstp qword ptr [ecx]",
            "mov esp, ebp",
            "pop ebp", "pop edi", "pop esi", "pop ebx",
            inout("eax") block.as_ptr() => _, lateout("ecx") _, lateout("edx") _,
            clobber_abi("C"),
        );
    }
    out
}

const SQRTF_ADDR: usize = 0x0040_EA20; // cdecl (f32) -> ST0 (f32 exact)

/// `sqrtf_wrapper(x)` through the original (f32-exact result).
unsafe fn sqrtf(x: f32) -> f32 {
    unsafe { call_st0(SQRTF_ADDR, 0, 0, 0, 0, 0, &[x.to_bits()]) as f32 }
}

// --- thunks and the in-game shadow -----------------------------------------------------------------

#[repr(C)]
#[derive(Clone, Copy)]
struct Pushad {
    edi: u32,
    esi: u32,
    ebp: u32,
    esp: u32,
    ebx: u32,
    edx: u32,
    ecx: u32,
    eax: u32,
}

#[repr(C)]
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
struct Regs {
    eax: u32,
    ecx: u32,
    edx: u32,
    ebx: u32,
    esi: u32,
    edi: u32,
    ebp: u32,
}

impl Regs {
    fn of(p: &Pushad) -> Regs {
        Regs { eax: p.eax, ecx: p.ecx, edx: p.edx, ebx: p.ebx, esi: p.esi, edi: p.edi, ebp: p.ebp }
    }
    fn get(&self, i: usize) -> u32 {
        [self.eax, self.ecx, self.edx, self.ebx, self.esi, self.edi, self.ebp][i]
    }
}

const REG_NAMES: [&str; 7] = ["eax", "ecx", "edx", "ebx", "esi", "edi", "ebp"];
/// EBX / ESI / EDI / EBP: callee-saved in every original here.
const SAVED: u8 = 8 | 16 | 32 | 64;

/// A thunk around `extern "C" fn entry(&mut Pushad, *const u32) -> u32` (the second argument is the
/// first stack argument). `eax`: the entry set `r.eax` itself; `st0`: the returned bits are an f32 handed
/// back on the x87 stack. The optional number is the original's `ret N`.
macro_rules! thunk4 {
    ($name:ident, $f:ident, eax) => { thunk4!(@ $name, $f, "nop", "ret"); };
    ($name:ident, $f:ident, eax, $n:literal) => { thunk4!(@ $name, $f, "nop", concat!("ret ", $n)); };
    ($name:ident, $f:ident, st0) => { thunk4!(@ $name, $f, "push eax\n fld dword ptr [esp]\n add esp, 4", "ret"); };
    (@ $name:ident, $f:ident, $conv:expr, $ret:expr) => {
        #[unsafe(naked)]
        extern "C" fn $name() {
            std::arch::naked_asm!(
                "pushad",
                "mov eax, esp",
                "lea ecx, [esp + 36]",
                "push ecx",
                "push eax",
                "call {f}",
                "add esp, 8",
                $conv,
                "popad",
                $ret,
                f = sym $f,
            )
        }
    };
}

#[repr(C)]
struct OBlk {
    f: u32,
    r: Regs,
    esp: u32,
    stk: u32,
    want_st0: u32,
    pad: u32,
    st0: [u32; 2],
    sw: u32,
    args: [u32; 12],
}

/// Call `f` (a `ret POP`-bytes callee, POP = 0 for cdecl) with all seven registers from `r` and twelve
/// stack argument slots; returns the registers after the call, ST0 (if `want_st0`) and the x87 status
/// word. `stk` != 0 runs it on that stack (the offline test).
unsafe fn call_orig_n<const POP: usize>(f: usize, r: &Regs, args: &[u32; 12], want_st0: bool, stk: u32) -> (Regs, f64, u32) {
    let mut b = OBlk { f: f as u32, r: *r, esp: 0, stk, want_st0: want_st0 as u32, pad: 0, st0: [0; 2], sw: 0, args: *args };
    unsafe {
        std::arch::asm!(
            "push ebp", "push ebx", "push esi", "push edi",
            "mov [eax + 32], esp",
            "mov ecx, [eax + 36]",
            "test ecx, ecx",
            "jz 4f",
            "mov esp, ecx",
            "4:",
            "push eax",
            "push dword ptr [eax]",
            "push dword ptr [eax + 104]", "push dword ptr [eax + 100]", "push dword ptr [eax + 96]", "push dword ptr [eax + 92]",
            "push dword ptr [eax + 88]", "push dword ptr [eax + 84]", "push dword ptr [eax + 80]", "push dword ptr [eax + 76]",
            "push dword ptr [eax + 72]", "push dword ptr [eax + 68]", "push dword ptr [eax + 64]", "push dword ptr [eax + 60]",
            "mov ecx, [eax + 8]", "mov edx, [eax + 12]", "mov ebx, [eax + 16]",
            "mov esi, [eax + 20]", "mov edi, [eax + 24]", "mov ebp, [eax + 28]",
            "mov eax, [eax + 4]",
            "call dword ptr [esp + 48]",
            "sub esp, {pop}",
            "push ebx",
            "mov ebx, [esp + 56]",
            "mov [ebx + 4], eax", "mov [ebx + 8], ecx", "mov [ebx + 12], edx",
            "mov [ebx + 20], esi", "mov [ebx + 24], edi", "mov [ebx + 28], ebp",
            "pop dword ptr [ebx + 16]",
            "fnstsw word ptr [ebx + 56]",
            "cmp dword ptr [ebx + 40], 0",
            "je 2f",
            "fstp qword ptr [ebx + 48]",
            "2:",
            "mov esp, [ebx + 32]",
            "pop edi", "pop esi", "pop ebx", "pop ebp",
            pop = const POP,
            inout("eax") &mut b as *mut OBlk => _,
            lateout("ecx") _,
            lateout("edx") _,
            clobber_abi("C"),
        );
    }
    (b.r, f64::from_bits(b.st0[0] as u64 | (b.st0[1] as u64) << 32), b.sw)
}

unsafe fn call_orig(f: usize, r: &Regs, args: &[u32; 12], pop: usize, want_st0: bool, stk: u32) -> (Regs, f64, u32) {
    unsafe {
        match pop {
            0 => call_orig_n::<0>(f, r, args, want_st0, stk),
            4 => call_orig_n::<4>(f, r, args, want_st0, stk),
            8 => call_orig_n::<8>(f, r, args, want_st0, stk),
            12 => call_orig_n::<12>(f, r, args, want_st0, stk),
            16 => call_orig_n::<16>(f, r, args, want_st0, stk),
            20 => call_orig_n::<20>(f, r, args, want_st0, stk),
            24 => call_orig_n::<24>(f, r, args, want_st0, stk),
            28 => call_orig_n::<28>(f, r, args, want_st0, stk),
            32 => call_orig_n::<32>(f, r, args, want_st0, stk),
            _ => call_orig_n::<36>(f, r, args, want_st0, stk),
        }
    }
}

struct Port {
    name: &'static str,
    addr: usize,
    /// Registers the original leaves unchanged on every path (checked in the shadow).
    preserved: u8,
    calls: AtomicU32,
    mismatches: AtomicU32,
    /// Number of calls that are shadowed (the first ones).
    window: u32,
    /// A relocated copy of the original (0: this port is not shadowed).
    original: AtomicUsize,
}

const fn port(name: &'static str, addr: usize, preserved: u8, window: u32) -> Port {
    Port { name, addr, preserved, calls: AtomicU32::new(0), mismatches: AtomicU32::new(0), window, original: AtomicUsize::new(0) }
}

fn is_nan32(b: u32) -> bool {
    b & 0x7F80_0000 == 0x7F80_0000 && b & 0x7F_FFFF != 0
}

/// What a port hands back.
#[derive(Clone, Copy, PartialEq)]
enum Rk {
    None,
    /// EAX (compared under the mask)
    Eax,
    /// an f32 on ST0
    St0,
}

#[cold]
#[inline(never)]
fn mismatch(p: &Port, n: u32, what: String) {
    let m = p.mismatches.fetch_add(1, Ordering::Relaxed) + 1;
    if m <= 10 {
        log(&format!("port_nav2: {} mismatch (call {n}): {what}", p.name));
    }
}

unsafe fn snap(regions: &[(usize, usize)]) -> Vec<Vec<u8>> {
    regions.iter().map(|&(a, n)| unsafe { std::slice::from_raw_parts(a as *const u8, n) }.to_vec()).collect()
}

unsafe fn restore(regions: &[(usize, usize)], s: &[Vec<u8>]) {
    for (&(a, _), b) in regions.iter().zip(s) {
        unsafe { std::ptr::copy_nonoverlapping(b.as_ptr(), a as *mut u8, b.len()) };
    }
}

/// The general shadow, for the first `window` calls of a port (a port keeps being checked after a
/// disagreement; the original's result and writes win). `regions` (computed from the pre-state, every byte
/// the original can write; `None` = cannot be bounded: `ours` just runs) are snapshotted around the
/// relocated original, then restored, `ours` runs and the memory, the result and the registers the
/// original preserves are compared. `args` points at the first stack argument, `nargs` dwords are passed to
/// the original, `pop` is the byte count it pops itself. `ours` returns the result bits (EAX, or the f32
/// bits for ST0).
unsafe fn shadow(
    pt: &Port,
    p: &Pushad,
    args: *const u32,
    nargs: usize,
    pop: usize,
    kind: Rk,
    eax_mask: u32,
    regions: impl FnOnce() -> Option<Vec<(usize, usize)>>,
    ours: impl FnOnce() -> u32,
) -> u32 {
    unsafe {
        let n = pt.calls.fetch_add(1, Ordering::Relaxed);
        let orig = pt.original.load(Ordering::Relaxed);
        if n == pt.window && orig != 0 {
            log(&format!("port_nav2: {}: {} calls shadowed, {} mismatched", pt.name, pt.window, pt.mismatches.load(Ordering::Relaxed)));
        }
        if orig == 0 || !(n < pt.window || pt.mismatches.load(Ordering::Relaxed) > 0) {
            return ours();
        }
        let Some(reg) = regions() else { return ours() };
        let mut a = [0u32; 12];
        for (i, x) in a.iter_mut().enumerate().take(nargs) {
            *x = *args.add(i);
        }
        let pre = snap(&reg);
        let inp = Regs::of(p);
        let (o, st0, _sw) = call_orig(orig, &inp, &a, pop, kind == Rk::St0, 0);
        for i in 0..7 {
            if pt.preserved & (1 << i) != 0 && inp.get(i) != o.get(i) {
                mismatch(pt, n, format!("the original changed {} ({:#x} -> {:#x})", REG_NAMES[i], inp.get(i), o.get(i)));
            }
        }
        let after_orig = snap(&reg);
        restore(&reg, &pre);
        let e = ours();
        let after_ours = snap(&reg);
        let theirs = match kind {
            Rk::Eax => o.eax,
            Rk::St0 => (st0 as f32).to_bits(),
            Rk::None => 0,
        };
        let same = match kind {
            Rk::Eax => (e ^ theirs) & eax_mask == 0,
            Rk::St0 => e == theirs || (is_nan32(e) && is_nan32(theirs)),
            Rk::None => true,
        };
        if after_ours != after_orig || !same {
            let diff = after_ours.iter().zip(&after_orig).position(|(x, y)| x != y);
            mismatch(pt, n, format!("in {inp:x?} args {a:x?}: original {theirs:#x}, Rust {e:#x}; first differing region {diff:?}"));
            restore(&reg, &after_orig);
            return theirs;
        }
        e
    }
}

/// Branch counters for the ports that cannot be shadowed.
static HITS: [AtomicU32; 48] = [const { AtomicU32::new(0) }; 48];
#[inline(always)]
fn hit(i: usize) {
    HITS[i].fetch_add(1, Ordering::Relaxed);
}

/// Quieted f32 bits, as `fld dword` + `fstp dword` leaves them.
fn quiet(bits: u32) -> u32 {
    if bits & 0x7F80_0000 == 0x7F80_0000 && bits & 0x007F_FFFF != 0 { bits | 0x0040_0000 } else { bits }
}

/// An f64 constant of the exe.
unsafe fn q64(a: usize) -> u64 {
    (rd(a) as u64) | (rd(a + 4) as u64) << 32
}

// =================================================================================================
// 0xA8A4F0 road_query_random_lane_setup (222 bytes)
// =================================================================================================
//
// EAX = &centre vec3, EDX = &out int, stack (cdecl, caller pops 0x18): (f32 radius, a, b, c, f32 d, f32 e).
// Void. `*edx = 0` first, then (`net = [0x2225B64]`, `tree = [net+0x84]`, both non-zero) the shared road
// query globals are written and the road tree walked with 0xBF77B0 (callbacks 0xA89A20 / 0xA89FC0, which
// read exactly these globals). EDI is the only register the original saves; EAX / ECX / EDX are clobbered
// (ECX = tree, EDX = 1 and then whatever the walk leaves). The three f32 arguments go through
// `fld dword` / `fstp dword` (a signalling NaN comes out quiet); the radius is also squared at 53 bits and
// rounded. Check: per-branch counters only (the tree walk has side effects), plus the offline test.

const ROAD_NET: usize = 0x0222_5B64;
const RQ_OUT: usize = 0x02FA_8D24;
const RQ_DEST: usize = 0x02FA_8D28;
const RQ_ONE: usize = 0x02FA_8CC8;
const RQ_CENTRE: usize = 0x02FA_8CD8;
const RQ_R2: usize = 0x02FA_8CFC;
const RQ_D: usize = 0x02FA_8D14;
const RQ_E: usize = 0x02FA_8D18;
const RQ_B: usize = 0x02FA_8CC0;
const RQ_A: usize = 0x02FA_8CC4;
const RQ_ZERO: usize = 0x02FA_8D0C;
const RQ_C: usize = 0x02FA_8D10;
const RQ_FLAG: usize = 0x02FA_8CCC;
const RQ_M1: usize = 0x02FA_8CD0;
const RQ_ZERO2: usize = 0x02FA_8CD4;
const ROAD_TREE_WALK: usize = 0x00BF_77B0;
const ROAD_TREE_CB: u32 = 0x00A8_9A20;
const ROAD_RANDOM_LANE_CB: u32 = 0x00A8_9FC0;

unsafe fn road_query_random_lane_setup(centre: u32, out: u32, esi: u32, args: *const u32) {
    unsafe {
        wd(out as usize, 0);
        let net = rd(ROAD_NET);
        if net == 0 {
            hit(0);
            return;
        }
        let tree = rd(net as usize + 0x84);
        if tree == 0 {
            hit(1);
            return;
        }
        hit(2);
        let (radius, a, b, c, d, e) = (*args, *args.add(1), *args.add(2), *args.add(3), *args.add(4), *args.add(5));
        let rq = quiet(radius);
        wd(RQ_OUT, out);
        // r * r at 53 bits, rounded to f32 (a NaN stays a NaN with its payload)
        let r2 = if is_nan32(radius) { rq } else { (((f32::from_bits(radius) as f64) * (f32::from_bits(radius) as f64)) as f32).to_bits() };
        wd(RQ_DEST, 0);
        wd(RQ_ONE, 1);
        let (cx, cy, cz) = (rd(centre as usize), rd(centre as usize + 4), rd(centre as usize + 8));
        wd(RQ_CENTRE, cx);
        wd(RQ_CENTRE + 4, cy);
        wd(RQ_R2, r2);
        wd(RQ_CENTRE + 8, cz);
        wd(RQ_D, quiet(d));
        wd(RQ_B, b);
        wd(RQ_E, quiet(e));
        wd(RQ_A, a);
        wd(RQ_ZERO, 0);
        wd(RQ_C, c);
        wb(RQ_FLAG, 1);
        wd(RQ_M1, 0xFFFF_FFFF);
        wd(RQ_ZERO2, 0);
        let t0 = rd(tree as usize);
        let t8 = rd(tree as usize + 8);
        // eax = [tree+8], ecx = tree, edx = [tree], esi as the caller left it, edi = c
        call_regs(ROAD_TREE_WALK, t8, tree, t0, esi, c, &[t8, centre, rq, t0, ROAD_TREE_CB, ROAD_RANDOM_LANE_CB]);
    }
}

extern "C" fn rq_setup_entry(r: &mut Pushad, args: *const u32) -> u32 {
    unsafe { road_query_random_lane_setup(r.eax, r.edx, r.esi, args) };
    0
}
thunk4!(rq_setup_thunk, rq_setup_entry, eax);

// =================================================================================================
// 0xA103B0 nav_tri_edge_midpoint (110 bytes)
// =================================================================================================
//
// ECX = &out vec3, EDI = cell, ESI = edge index i: out = (v[(i+1)%3] + v[i]) * 0.5 with the sum rounded to
// f32 before the halving (`fstp dword` between). The wrap is a signed `idiv` by 3 (a negative or large `i`
// reads the pointer slots around the cell). Saves EBX; leaves EAX = z bits and EDX = y bits of the result.

const HALF: u64 = 0x3FE0_0000_0000_0000;

/// The midpoint of edge `i` of `cell` as three f32 bit patterns.
unsafe fn tri_edge_mid(cell: u32, i: u32) -> [u32; 3] {
    unsafe {
        let r = (i as i32).wrapping_add(1) % 3;
        let pa = rd((cell as usize).wrapping_add((i as usize).wrapping_mul(4))) as usize;
        let pb = rd((cell as usize).wrapping_add((r as isize as usize).wrapping_mul(4))) as usize;
        let half = f64::from_bits(HALF);
        let mut o = [0u32; 3];
        for k in 0..3 {
            let s = (rf(pb + 4 * k) as f64 + rf(pa + 4 * k) as f64) as f32;
            o[k] = (((s as f64) * half) as f32).to_bits();
        }
        o
    }
}

extern "C" fn mid_entry(r: &mut Pushad, _args: *const u32) -> u32 {
    let p = *r;
    let y = std::cell::Cell::new(0u32);
    unsafe {
        let v = shadow(&PORTS[P_MID], &p, _args, 0, 0, Rk::Eax, u32::MAX, || Some(vec![(p.ecx as usize, 12)]), || {
            let o = tri_edge_mid(p.edi, p.esi);
            wd(p.ecx as usize, o[0]);
            wd(p.ecx as usize + 4, o[1]);
            wd(p.ecx as usize + 8, o[2]);
            y.set(o[1]);
            o[2]
        });
        // EDX = the y bits (the original's `mov edx, [esp+0x10]`), EAX = the z bits
        r.edx = y.get();
        r.eax = v;
    }
    0
}
thunk4!(mid_thunk, mid_entry, eax);

// =================================================================================================
// 0xA11750 nav_cells_heuristic (1,214 bytes)
// =================================================================================================
//
// cdecl, caller pops 0x14: (cellA, &posA, cellB, &posB, wide) -> ST0 (an f32). Saves EBX, EBP, ESI, EDI.
// M0 = max over the open edges i of A (neighbour pointer [A+0xC+4i] != 0) of |posA - midA_i|^2, M1 the same
// for B / posB, M2 = max over open edges i of A and j of B of |midA_i - midB_j|^2 (i outer, j inner); each
// |.|^2 is dx*dx (rounded f32), then + dy*dy (the product stays f64, the sum is rounded), then + dz*dz, with
// the differences rounded to f32 first. A max keeps the old value only when `new < old` (the x87
// `test ah,5; jnp`: ties, NaNs replace), starting from 0.0. Then
//   est = (sqrtf(M0) + sqrtf(M1) + sqrtf(M2)) * 1.5 + 100.0    (the sqrt calls run M1, M0, M2; the first
//                                                               sum is kept as an f64, as in the original)
// stored as f32, and clamped: wide (low byte of the last argument != 0): est < 300.0f ? est : 300.0f;
// otherwise est < 200.0 (f64 compare) ? est : [0xDD0C4C] (200.0f).

const C_1_5: u64 = 0x3FF8_0000_0000_0000;
const C_100: u64 = 0x4059_0000_0000_0000;
const C_200: u64 = 0x4069_0000_0000_0000;
const CAP_WIDE_ADDR: usize = 0x00E8_E0D8;
const CAP_NARROW_ADDR: usize = 0x00DD_0C4C;

/// |p - m|^2 the way the original accumulates it.
fn dist2_f32(p: [f32; 3], m: [f32; 3]) -> f32 {
    let dx = (p[0] as f64 - m[0] as f64) as f32;
    let t = (dx as f64 * dx as f64) as f32;
    let dy = (p[1] as f64 - m[1] as f64) as f32;
    let t = (dy as f64 * dy as f64 + t as f64) as f32;
    let dz = (p[2] as f64 - m[2] as f64) as f32;
    (dz as f64 * dz as f64 + t as f64) as f32
}

/// The max update: keep `m` only when `v < m` (ordered).
#[inline(always)]
fn max_upd(m: f32, v: f32) -> f32 {
    if v < m { m } else { v }
}

unsafe fn vec3_at(p: u32) -> [f32; 3] {
    unsafe { [rf(p as usize), rf(p as usize + 4), rf(p as usize + 8)] }
}

unsafe fn nav_cells_heuristic(ca: u32, pa: u32, cb: u32, pb: u32, wide: u32) -> f32 {
    unsafe {
        let mut ma = [[0f32; 3]; 3];
        let mut mb = [[0f32; 3]; 3];
        for i in 0..3u32 {
            let a = tri_edge_mid(ca, i);
            let b = tri_edge_mid(cb, i);
            ma[i as usize] = [f32::from_bits(a[0]), f32::from_bits(a[1]), f32::from_bits(a[2])];
            mb[i as usize] = [f32::from_bits(b[0]), f32::from_bits(b[1]), f32::from_bits(b[2])];
        }
        let na = [rd(ca as usize + 0xC) != 0, rd(ca as usize + 0x10) != 0, rd(ca as usize + 0x14) != 0];
        let nb = [rd(cb as usize + 0xC) != 0, rd(cb as usize + 0x10) != 0, rd(cb as usize + 0x14) != 0];
        let (posa, posb) = (vec3_at(pa), vec3_at(pb));
        let mut m0 = 0f32;
        for i in 0..3 {
            if na[i] {
                m0 = max_upd(m0, dist2_f32(posa, ma[i]));
            }
        }
        let mut m1 = 0f32;
        for j in 0..3 {
            if nb[j] {
                m1 = max_upd(m1, dist2_f32(posb, mb[j]));
            }
        }
        let mut m2 = 0f32;
        for i in 0..3 {
            if na[i] {
                for j in 0..3 {
                    if nb[j] {
                        m2 = max_upd(m2, dist2_f32(ma[i], mb[j]));
                    }
                }
            }
        }
        let s1 = sqrtf(m1);
        let s0 = sqrtf(m0);
        let sum01 = s0 as f64 + s1 as f64;
        let s2 = sqrtf(m2);
        let est = ((s2 as f64 + sum01) * f64::from_bits(C_1_5) + f64::from_bits(C_100)) as f32;
        if wide & 0xFF != 0 {
            let cap = f32::from_bits(0x4396_0000);
            if est < cap { est } else { cap }
        } else if (est as f64) < f64::from_bits(C_200) {
            est
        } else {
            f32::from_bits(0x4348_0000)
        }
    }
}

extern "C" fn heur_entry(r: &mut Pushad, args: *const u32) -> u32 {
    let p = *r;
    unsafe {
        shadow(&PORTS[P_HEUR], &p, args, 5, 0, Rk::St0, 0, || Some(vec![]), || {
            nav_cells_heuristic(*args, *args.add(1), *args.add(2), *args.add(3), *args.add(4)).to_bits()
        })
    }
}
thunk4!(heur_thunk, heur_entry, st0);

// =================================================================================================
// 0xA16650 nav_poly_link_match (3,319 bytes' worth of x87; the job stage of nav_timesliced_jobs_update)
// =================================================================================================
//
// cdecl, caller pops 8: (item*, rec*), no result. Saves EBX, EBP, ESI, EDI. `item` = {+0 vec3** vertex
// pointers, +4 u32* out (two dwords), +8 u16 n}; `rec` = {+8 u16 id, +0x28 minX, +0x30 minZ, +0x34 maxX,
// +0x3C maxZ (f32), +0x14C link count, +0x150 links (0x20 bytes: start x @0, z @8; end x @0xC, z @0x14;
// key @0x1C)}. Decoded from the disassembly (the doc's polarities are corrected where they differ):
//  1. bounding box (x, z) of the n vertices: a min is replaced unless `v > min`, a max unless `v < max`
//     (so ties and NaNs replace), starting from vertex 0;
//  2. exit when the box misses rec's bounds (`rec.maxX < minX`, `maxX < rec.minX`, `rec.maxZ < minZ`,
//     `maxZ < rec.minZ`; ordered compares);
//  3. longest edge i -> (i+1)%n (signed idiv): e = (dx, 0, dz) rounded to f32, l2 = f32(dz*dz + dx*dx);
//     replaced when `l2 > best` (ties do NOT replace) or when `best < 0` (best starts at -1.0, so the
//     first edge always replaces); edge starts as (zero.x, minZ bits, zero.z) (only n == 0 sees that);
//  4. nrm = normalize((edge.z, 0, -edge.x)) through 0xBDDFF0 (ESI = buffer);
//  5. d_k = f32((dy*ny + dx*nx) + dz*nz) for k = 1..n-1 (differences to vertex 0 rounded to f32, products
//     and sums at 53 bits); lo = min (replaced unless `d > lo`), hi = max (replaced unless `hi > d`); the
//     first d sets both; width = f32(hi - lo) (>= 0);
//  6. centroid: sequential f32 sums of x and z over vertices 0..n-1, times f32(1/n);
//  7. r2 = f32((width*0.5 + 0.25)^2); link count <= 0 -> exit;
//  8. nearest link: skip a link whose start and end (x, z) are equal; q = 0xBE6C50(start, end, centroid);
//     d2 = f32(dz*dz + dx*dx); take when `best > d2`;
//  9. out[0] = (id << 16) | ((idx + 1) & 0xFFFF); key >= 0: out[1] = the first other link with the same
//     key; key < 0: the first other link whose end points match this one's within width (either
//     direction), whose length differs by <= 0.25 and whose |direction dot| >= 0.9994.

const NEG_ONE_ADDR: usize = 0x00E8_7998;
const ZERO_VEC_ADDR: usize = 0x0252_A6D0;
const QUARTER: u64 = 0x3FD0_0000_0000_0000;
const LEN_TOL_ADDR: usize = 0x00E4_4850;
const DOT_MIN: u64 = 0x3FEF_FB15_C000_0000;
const VEC3_NORMALIZE_ADDR: usize = 0x00BD_DFF0; // ESI = &v, normalizes in place
const VEC3_NORMALIZE_LEN_ADDR: usize = 0x00BD_E060; // ESI = &v, normalizes in place, XMM0 = the length
const SEG_CLOSEST_XZ_ADDR: usize = 0x00BE_6C50; // ECX = &a (x, z), EDX = &b, EDI = &p, ESI = &out (x, z)

/// Call a game function that returns an f32 in XMM0 (the low 32 bits come back).
unsafe fn call_xmm0(f: usize, eax: u32, ecx: u32, edx: u32, esi: u32, edi: u32, args: &[u32]) -> u32 {
    let f = tgt(f);
    let mut out = 0u32;
    let block: [u32; 9] = [f as u32, ecx, edx, esi, edi, args.as_ptr() as u32, args.len() as u32, eax, &mut out as *mut u32 as u32];
    unsafe {
        std::arch::asm!(
            "push ebx", "push esi", "push edi", "push ebp",
            "mov ebp, esp",
            "mov ebx, eax",
            "mov ecx, [ebx + 24]",
            "mov esi, [ebx + 20]",
            "2:",
            "test ecx, ecx",
            "jz 3f",
            "push dword ptr [esi + ecx*4 - 4]",
            "dec ecx",
            "jmp 2b",
            "3:",
            "mov ecx, [ebx + 4]", "mov edx, [ebx + 8]", "mov esi, [ebx + 12]", "mov edi, [ebx + 16]",
            "mov eax, [ebx + 28]",
            "call dword ptr [ebx]",
            "mov ecx, [ebx + 32]",
            "movss dword ptr [ecx], xmm0",
            "mov esp, ebp",
            "pop ebp", "pop edi", "pop esi", "pop ebx",
            inout("eax") block.as_ptr() => _, lateout("ecx") _, lateout("edx") _,
            clobber_abi("C"),
        );
    }
    out
}

/// An f32 loaded and stored again on the x87 (a signalling NaN comes out quiet).
#[inline(always)]
fn qf(x: f32) -> f32 {
    f32::from_bits(quiet(x.to_bits()))
}

/// |a - b|^2 as the original accumulates it (differences rounded to f32, `dx*dx` rounded, `dy*dy` added at
/// 53 bits and rounded, `dz*dz` likewise).
fn dist2_3(a: [f32; 3], b: [f32; 3]) -> f32 {
    dist2_f32(a, b)
}

unsafe fn nav_poly_link_match(item: u32, rec: u32) {
    unsafe {
        let vp = rd(item as usize) as usize;
        let outp = rd(item as usize + 4) as usize;
        let n = rw(item as usize + 8);
        let v = |k: u32| rd(vp + 4 * k as usize) as usize;
        let v0 = v(0);
        // 1. bounding box
        let (mut minx, mut minz) = (qf(rf(v0)), qf(rf(v0 + 8)));
        let (mut maxx, mut maxz) = (minx, minz);
        for k in 1..n {
            let p = v(k);
            let (x, z) = (rf(p), rf(p + 8));
            if !(x > minx) {
                minx = qf(x);
            }
            if !(z > minz) {
                minz = qf(z);
            }
            if !(x < maxx) {
                maxx = qf(x);
            }
            if !(z < maxz) {
                maxz = qf(z);
            }
        }
        // 2. reject
        let r = rec as usize;
        let (rminx, rminz, rmaxx, rmaxz) = (rf(r + 0x28), rf(r + 0x30), rf(r + 0x34), rf(r + 0x3C));
        if rmaxx < minx || maxx < rminx || rmaxz < minz || maxz < rminz {
            return;
        }
        // 3. longest edge
        let mut best = qf(rf(NEG_ONE_ADDR));
        let mut edge = [qf(rf(ZERO_VEC_ADDR)), minz, qf(rf(ZERO_VEC_ADDR + 8))];
        for i in 0..n {
            let next = ((i + 1) as i32 % n as i32) as u32;
            let (a, b) = (v(i), v(next));
            let ex = (rf(b) as f64 - rf(a) as f64) as f32;
            let ez = (rf(b + 8) as f64 - rf(a + 8) as f64) as f32;
            let l2 = (ez as f64 * ez as f64 + ex as f64 * ex as f64) as f32;
            if l2 > best || best < 0.0 {
                best = l2;
                edge = [ex, 0.0, ez];
            }
        }
        // 4. the normal
        let mut nrm = [edge[2], 0.0f32, f32::from_bits(edge[0].to_bits() ^ 0x8000_0000)];
        call_regs(VEC3_NORMALIZE_ADDR, 0, 0, 0, nrm.as_mut_ptr() as u32, 0, &[]);
        let (nx, ny, nz) = (nrm[0] as f64, nrm[1] as f64, nrm[2] as f64);
        // 5. the extent along it
        let (mut lo, mut hi) = (0f32, 0f32);
        for k in 1..n {
            let p = v(k);
            let ex = (rf(p) as f64 - rf(v0) as f64) as f32 as f64;
            let ey = (rf(p + 4) as f64 - rf(v0 + 4) as f64) as f32 as f64;
            let ez = (rf(p + 8) as f64 - rf(v0 + 8) as f64) as f32 as f64;
            let d = (((ey * ny + ex * nx) + ez * nz) as f32) as f32;
            if k == 1 {
                lo = d;
                hi = d;
            } else {
                if !(d > lo) {
                    lo = d;
                }
                if !(hi > d) {
                    hi = d;
                }
            }
        }
        let width = (hi as f64 - lo as f64) as f32;
        // 6. the centroid
        let (mut sx, mut sz) = (0f32, 0f32);
        for k in 0..n {
            let p = v(k);
            sx = (sx as f64 + rf(p) as f64) as f32;
            sz = (rf(p + 8) as f64 + sz as f64) as f32;
        }
        let inv = (1.0f64 / n as f64) as f32;
        let cx = (inv as f64 * sx as f64) as f32;
        let cz = (inv as f64 * sz as f64) as f32;
        // 7. the radius
        let count = rd(r + 0x14C) as i32;
        let links = rd(r + 0x150) as usize;
        let t = width as f64 * f64::from_bits(HALF) + f64::from_bits(QUARTER);
        let mut bestd = (t * t) as f32;
        if count <= 0 {
            return;
        }
        // 8. the nearest link
        let mut idx: i32 = -1;
        let cen = [cx, cz];
        for i in 0..count {
            let l = links + 0x20 * i as usize;
            let p0 = [qf(rf(l)), qf(rf(l + 8))];
            let p1 = [qf(rf(l + 0xC)), qf(rf(l + 0x14))];
            if p0[0] == p1[0] && p0[1] == p1[1] {
                continue;
            }
            let mut q = [0f32; 2];
            call_regs(SEG_CLOSEST_XZ_ADDR, 0, p0.as_ptr() as u32, p1.as_ptr() as u32, q.as_mut_ptr() as u32, cen.as_ptr() as u32, &[]);
            let dx = (q[0] as f64 - cx as f64) as f32;
            let dz = (q[1] as f64 - cz as f64) as f32;
            let d2 = (dz as f64 * dz as f64 + dx as f64 * dx as f64) as f32;
            if bestd > d2 {
                bestd = d2;
                idx = i;
            }
        }
        if idx < 0 {
            return;
        }
        // 9. the refs
        let id = rw(r + 8);
        wd(outp, (id << 16) | ((idx as u32 + 1) & 0xFFFF));
        let l = links + 0x20 * idx as usize;
        let key = rd(l + 0x1C);
        let links2 = rd(r + 0x150) as usize;
        let count2 = rd(r + 0x14C) as i32;
        if (key as i32) >= 0 {
            for j in 0..count2 {
                if rd(links2 + 0x20 * j as usize + 0x1C) == key && j != idx {
                    wd(outp + 4, (id << 16) | ((j as u32 + 1) & 0xFFFF));
                    return;
                }
            }
            return;
        }
        // key < 0: the reversed twin
        let l = links2 + 0x20 * idx as usize;
        let mut dir = [
            (rf(l + 0xC) as f64 - rf(l) as f64) as f32,
            (rf(l + 0x10) as f64 - rf(l + 4) as f64) as f32,
            (rf(l + 0x14) as f64 - rf(l + 8) as f64) as f32,
        ];
        let len = qf(f32::from_bits(call_xmm0(VEC3_NORMALIZE_LEN_ADDR, 0, 0, 0, dir.as_mut_ptr() as u32, 0, &[])));
        let count3 = rd(r + 0x14C) as i32;
        if count3 <= 0 {
            return;
        }
        let w2 = width as f64 * width as f64;
        let s = [rf(l), rf(l + 4), rf(l + 8)];
        let e = [rf(l + 0xC), rf(l + 0x10), rf(l + 0x14)];
        for j in 0..count3 {
            let m = links2 + 0x20 * j as usize;
            if m == l {
                continue;
            }
            let ms = [rf(m), rf(m + 4), rf(m + 8)];
            let me = [rf(m + 0xC), rf(m + 0x10), rf(m + 0x14)];
            let a = dist2_3(s, ms) as f64;
            if a <= w2 {
                // same direction: the end points must agree too
                if dist2_3(e, me) as f64 > w2 {
                    continue;
                }
            } else {
                // reversed
                let a2 = dist2_3(s, me) as f64;
                if !(a2 <= w2) {
                    continue;
                }
                if dist2_3(e, ms) as f64 > w2 {
                    continue;
                }
            }
            let mut md = [
                (me[0] as f64 - ms[0] as f64) as f32,
                (me[1] as f64 - ms[1] as f64) as f32,
                (me[2] as f64 - ms[2] as f64) as f32,
            ];
            let len2 = f32::from_bits(call_xmm0(VEC3_NORMALIZE_LEN_ADDR, 0, 0, 0, md.as_mut_ptr() as u32, 0, &[]));
            let diff = ((len as f64 - len2 as f64).abs()) as f32;
            if diff > f32::from_bits(0x3E80_0000) {
                continue;
            }
            let dot = ((md[0] as f64 * dir[0] as f64 + md[1] as f64 * dir[1] as f64) + md[2] as f64 * dir[2] as f64) as f32;
            let dot = dot.abs();
            if (dot as f64) < f64::from_bits(DOT_MIN) {
                continue;
            }
            wd(outp + 4, (id << 16) | ((j as u32 + 1) & 0xFFFF));
            return;
        }
    }
}

extern "C" fn link_entry(r: &mut Pushad, args: *const u32) -> u32 {
    let p = *r;
    unsafe {
        shadow(&PORTS[P_LINK], &p, args, 2, 0, Rk::None, 0, || Some(vec![(rd(*args as usize + 4) as usize, 8)]), || {
            nav_poly_link_match(*args, *args.add(1));
            0
        })
    }
}
thunk4!(link_thunk, link_entry, eax);

// =================================================================================================
// The open-list helpers and nav_cells_reachable
// =================================================================================================
//
// Shared state (doc 59 2.0): generation 0x2E160BC, scratch count 0x2E160C0, 24-byte scratch records at
// 0x2E160C4 (g +0, h +4, pos +8, s8 edge +0x14, open +0x15, heap index u16 +0x16), selected by u16
// [cell+0x1E] and valid when [cell+0x20] == generation; open heap count 0x2E2E0C4 and cell pointers at
// 0x2E2E0C8. Where the original writes through a null scratch pointer (a cell whose generation is stale: a
// guaranteed fault) the port skips the write instead (deviation, never reached in a healthy search).

const GEN: usize = 0x02E1_60BC;
const SCR_CNT: usize = 0x02E1_60C0;
const SCR: usize = 0x02E1_60C4;
const BUSY: usize = 0x02E1_60B8;
const HEAP_CNT: usize = 0x02E2_E0C4;
const HEAP: usize = 0x02E2_E0C8;
const VIS_CNT: usize = 0x0252_9820;
const VIS: usize = 0x021F_C1A0;
const SIFT_DOWN: usize = 0x00A1_0110;
const RELAX: usize = 0x00A0_4790;
const HAS_LINK2: usize = 0x00A0_5460;
const TRI_CENTROID: usize = 0x00A0_FE30;
const VEC3_DIST2: usize = 0x0040_4A20;
const CELLS_HEURISTIC: usize = 0x00A1_1750;
const POP_ADDR: usize = 0x00A1_0080;

/// The scratch record of `cell`, if its generation is current.
#[inline(always)]
unsafe fn scratch_of(cell: usize) -> Option<usize> {
    unsafe {
        if rd(cell + 0x20) == rd(GEN) { Some(SCR + rw(cell + 0x1E) as usize * 24) } else { None }
    }
}

/// The regions the heap helpers can write: the scratch table, the heap and its count.
fn heap_regions() -> Option<Vec<(usize, usize)>> {
    Some(vec![(SCR, 0x1000 * 24), (HEAP, 0x4000), (HEAP_CNT, 4)])
}

// --- 0xA10080 nav_open_list_pop (no args -> EAX = cell with the smallest g+h, or 0) ----------------------

unsafe fn nav_open_list_pop() -> u32 {
    unsafe {
        let count = rd(HEAP_CNT) as i32;
        if count <= 0 {
            hit(8);
            return 0;
        }
        let root = rd(HEAP);
        if count > 1 {
            hit(10);
            let last = rd(HEAP + (count as usize - 1) * 4);
            wd(HEAP, last);
            if let Some(r) = scratch_of(last as usize) {
                ww(r + 0x16, 0);
            }
            wd(HEAP_CNT, (count - 1) as u32);
            call_regs(SIFT_DOWN, 0, 0, 0, 0, 0, &[0]);
        } else {
            hit(9);
            wd(HEAP_CNT, 0);
        }
        if let Some(r) = scratch_of(root as usize) {
            wb(r + 0x15, 0);
        }
        root
    }
}

extern "C" fn pop_entry(r: &mut Pushad, args: *const u32) -> u32 {
    let p = *r;
    unsafe {
        let v = shadow(&PORTS[P_POP], &p, args, 0, 0, Rk::Eax, u32::MAX, heap_regions, || nav_open_list_pop());
        r.eax = v;
    }
    0
}
thunk4!(pop_thunk, pop_entry, eax);

// --- 0xA10260 nav_open_list_sift_up (stack: heap index, ret 4) ------------------------------------------
//
// Moves the entry at `idx` up while its key (f32(h + g)) is smaller than its parent's (`item < parent`,
// ordered), keeping each moved parent's heap index current, then stores the item and calls sift_down(idx).

#[inline(always)]
unsafe fn heap_key(cell: u32) -> f32 {
    unsafe {
        let r = SCR + rw(cell as usize + 0x1E) as usize * 24;
        (rf(r + 4) as f64 + rf(r) as f64) as f32
    }
}

/// Returns the f32 key bits the original leaves in ECX (it keeps its temporaries in the slot where it saved
/// ECX): the item's key when the loop was entered (0 < idx < count), else None (ECX unchanged).
unsafe fn nav_open_list_sift_up(idx0: u32) -> Option<u32> {
    unsafe {
        let count = rd(HEAP_CNT) as i32;
        let mut idx = idx0 as i32;
        if idx >= count {
            hit(11);
            return None;
        }
        let item = rd(HEAP + idx as usize * 4);
        let key = heap_key(item);
        let entered = idx > 0;
        while idx > 0 {
            let par = (idx - 1) >> 1;
            let pc = rd(HEAP + par as usize * 4);
            if !(key < heap_key(pc)) {
                break;
            }
            hit(12);
            wd(HEAP + idx as usize * 4, pc);
            if let Some(r) = scratch_of(pc as usize) {
                ww(r + 0x16, idx as u16);
            }
            idx = par;
        }
        wd(HEAP + idx as usize * 4, item);
        if let Some(r) = scratch_of(item as usize) {
            ww(r + 0x16, idx as u16);
        }
        call_regs(SIFT_DOWN, 0, 0, 0, 0, 0, &[idx as u32]);
        if entered { Some(key.to_bits()) } else { None }
    }
}

extern "C" fn sift_up_entry(r: &mut Pushad, args: *const u32) -> u32 {
    let p = *r;
    let ecx = std::cell::Cell::new(None);
    unsafe {
        shadow(&PORTS[P_SIFT_UP], &p, args, 1, 4, Rk::None, 0, heap_regions, || {
            ecx.set(nav_open_list_sift_up(*args));
            0
        });
    }
    if let Some(e) = ecx.get() {
        r.ecx = e;
    }
    0
}
thunk4!(sift_up_thunk, sift_up_entry, eax, 4);

// --- 0xA12AE0 nav_visited_clear -------------------------------------------------------------------------
//
// Clears bit 0x10 of [cell+0x1D] for the `0x2529820` cells in 0x21FC1A0[] and zeroes the count (at most 0x20
// cells are visited: the list has 32 slots; the original reads on unbounded). Clobbers EAX, ECX, EDX.

unsafe fn nav_visited_clear() {
    unsafe {
        let n = rd(VIS_CNT) as i32;
        let mut i = 0;
        while i < n.min(0x20) {
            let c = rd(VIS + i as usize * 4) as usize;
            wb(c + 0x1D, rb(c + 0x1D) & 0xEF);
            i += 1;
        }
        wd(VIS_CNT, 0);
    }
}

extern "C" fn vclear_entry(r: &mut Pushad, args: *const u32) -> u32 {
    let p = *r;
    unsafe {
        shadow(
            &PORTS[P_VCLEAR],
            &p,
            args,
            0,
            0,
            Rk::None,
            0,
            || {
                let n = (rd(VIS_CNT) as i32).clamp(0, 0x20);
                let mut v = vec![(VIS_CNT, 4)];
                for i in 0..n as usize {
                    v.push((rd(VIS + i * 4) as usize + 0x1D, 1));
                }
                Some(v)
            },
            || {
                nav_visited_clear();
                0
            },
        )
    }
}
thunk4!(vclear_thunk, vclear_entry, eax);

// --- 0xA14230 nav_cells_reachable (cdecl, caller pops 0xC: cellA, cellB, flags*) -> AL ------------------
//
// h0 = nav_cells_heuristic(A, centroid(A), B, centroid(B), (flags[1] >> 6) & 1); an inline nav_search_begin;
// seed relax(A); then pop cells: B (popped, or met as a neighbour) -> 1; the three neighbours k of the cell
// (skipping the edge it was entered by, nulls, closed scratch records, flag 0x10, link-flag tests, the
// one-way test) cost g = f32(rec.g + sqrtf(dist2(centroid(cur), src))), pruned when `h0 <= g` (ordered),
// otherwise relax(nb, centroid(cur), cur, g, B); relax failing or the heap draining -> 0. The busy byte is
// cleared on every exit. Check: per-branch counters (it rewrites cells' scratch fields through relax).

unsafe fn nav_cells_reachable(ca: u32, cb: u32, flags: u32) -> u8 {
    unsafe {
        let mut c_a = [0f32; 3];
        let mut c_b = [0f32; 3];
        call_regs(TRI_CENTROID, 0, 0, ca, c_a.as_mut_ptr() as u32, 0, &[]);
        call_regs(TRI_CENTROID, 0, 0, cb, c_b.as_mut_ptr() as u32, 0, &[]);
        let wide = (rb(flags as usize + 1) >> 6) as u32 & 1;
        let ba = c_a.as_ptr() as u32;
        let bb = c_b.as_ptr() as u32;
        let h0 = call_st0(CELLS_HEURISTIC, 0, 0, 0, 0, 0, &[ca, ba, cb, bb, wide]) as f32;
        // inline nav_search_begin
        let g = rd(GEN).wrapping_add(1);
        wd(GEN, g);
        wd(SCR_CNT, 0);
        wd(HEAP_CNT, 0);
        if g == 0 {
            wd(GEN, 1);
        }
        wb(BUSY, 1);
        let ok = call_regs(RELAX, ca, ba, 0, 0, 0, &[0, 0f32.to_bits(), bb]) as u8;
        if ok == 0 || (rd(HEAP_CNT) as i32) <= 0 {
            hit(7);
            wb(BUSY, 0);
            return 0;
        }
        let f0 = rb(flags as usize);
        loop {
            let cur = POP_CALL();
            if cur == cb {
                hit(3);
                wb(BUSY, 0);
                return 1;
            }
            let rec = scratch_of(cur as usize);
            let edge = rec.map_or(-1, |r| rb(r + 0x14) as i8);
            let sp = match rec {
                Some(r) if edge >= 0 => r + 8,
                _ => 0,
            };
            let src: [f32; 3] = if sp != 0 {
                [qf(rf(sp)), qf(rf(sp + 4)), qf(rf(sp + 8))]
            } else {
                [qf(c_b[0]), qf(c_b[1]), qf(c_b[2])]
            };
            for k in 0..3i32 {
                if k == edge as i32 {
                    continue;
                }
                let nb = rd(cur as usize + 0xC + 4 * k as usize);
                if nb == 0 {
                    continue;
                }
                if nb == cb {
                    hit(4);
                    wb(BUSY, 0);
                    return 1;
                }
                if let Some(r) = scratch_of(nb as usize) {
                    if rb(r + 0x15) == 0 {
                        continue;
                    }
                }
                let nf = rb(nb as usize + 0x1D);
                if nf & 0x10 != 0 {
                    continue;
                }
                if nf & 2 != 0 && call_regs(HAS_LINK2, nb, 0, 0, 0, 0, &[]) as u8 == 0 {
                    continue;
                }
                if f0 & 0x10 != 0 && nb != ca && call_regs(HAS_LINK2, nb, 0, 0, 0, 0, &[]) as u8 != 0 {
                    continue;
                }
                if f0 & 8 == 0 && rb(cur as usize + 0x1D) & 1 != 0 && nf & 1 == 0 {
                    continue;
                }
                let mut c2 = [0f32; 3];
                call_regs(TRI_CENTROID, 0, 0, cur, c2.as_mut_ptr() as u32, 0, &[]);
                let d2 = call_st0(VEC3_DIST2, c2.as_ptr() as u32, src.as_ptr() as u32, 0, 0, 0, &[]) as f32;
                let d = sqrtf(d2);
                let rg = rec.map_or(0f32, |r| rf(r));
                let gg = (rg as f64 + d as f64) as f32;
                if h0 <= gg {
                    continue;
                }
                let ok = call_regs(RELAX, nb, c2.as_ptr() as u32, 0, 0, 0, &[cur, gg.to_bits(), bb]) as u8;
                if ok == 0 {
                    hit(5);
                    wb(BUSY, 0);
                    return 0;
                }
            }
            if (rd(HEAP_CNT) as i32) <= 0 {
                hit(6);
                wb(BUSY, 0);
                return 0;
            }
        }
    }
}

/// The pop callee, by address (the original calls 0xA10080).
#[allow(non_snake_case)]
unsafe fn POP_CALL() -> u32 {
    unsafe { call_regs(POP_ADDR, 0, 0, 0, 0, 0, &[]) }
}

extern "C" fn reach_entry(r: &mut Pushad, args: *const u32) -> u32 {
    let p = *r;
    let v = unsafe { nav_cells_reachable(*args, *args.add(1), *args.add(2)) };
    r.eax = (p.eax & !0xFF) | v as u32;
    0
}
thunk4!(reach_thunk, reach_entry, eax);

// =================================================================================================
// Vehicle pathfind entry points (0xB28700 navmesh; see the notes at each)
// =================================================================================================
//
// Shared pieces. `human_owned_locally(EAX = vehicle)` (0x806720, AL != 0 = local) picks the local order /
// goal install; otherwise a veh_pkt 0x1C packet is built on the stack and sent with 0x814670 (ESI = the
// connection from 0x80FE80(EAX = [0x2528C14], DL = the vehicle's conn id byte)). `di` is the u16 write
// offset; the packet buffer is 0x510 bytes (count <= 0x19 keeps the payload under 320). The original's
// /GS cookie check has no counterpart here. Uninitialised padding of the stack blocks the original passes
// on (the goal block's gaps, the options block's gaps) is zero here.

const OWNED_LOCALLY: usize = 0x0080_6720;
const FIND_CONN: usize = 0x0080_FE80;
const NET_SEND: usize = 0x0081_4670;
const ORDER_05: usize = 0x00B4_AAF0;
const GOAL_INSTALL: usize = 0x00B2_EE60;
const NET_SESSION: usize = 0x0252_8C14;
const NET_EXTRA_BYTE: usize = 0x00E8_BBFC;
const OBJ_POOL: usize = 0x0214_9C64;
const GOAL_F1: usize = 0x00E3_8AE0;
const GOAL_F2: usize = 0x00E8_725C;

/// The vehicle's net id as the packet builders compute it: the u16 at [[pool obj + 0xB0] + 2] when the
/// vehicle's handle names a live pool object, else the low 16 bits of the handle; 0xFFFF for no vehicle.
unsafe fn veh_net_id(v: u32) -> u16 {
    unsafe {
        if v == 0 {
            return 0xFFFF;
        }
        let h = rd(v as usize + 0x44);
        let mut id = 0xFFFFu32;
        if h != 0 {
            let obj = rd(OBJ_POOL + (((h & 0xFFF) as usize) << 4));
            if obj != 0 && rd(obj as usize + 0x44) == h {
                let b = rd(obj as usize + 0xB0);
                if b != 0 {
                    id = rw(b as usize + 2);
                }
            }
        }
        if id as u16 == 0xFFFF { rw(v as usize + 0x44) as u16 } else { id as u16 }
    }
}

struct Pkt {
    buf: [u8; 0x510],
    di: u32,
}

impl Pkt {
    fn put8(&mut self, v: u8) {
        self.buf[(self.di & 0xFFFF) as usize] = v;
        self.di += 1;
    }
    fn put16(&mut self, v: u16) {
        let i = (self.di & 0xFFFF) as usize;
        self.buf[i..i + 2].copy_from_slice(&v.to_le_bytes());
        self.di += 2;
    }
    fn put32(&mut self, v: u32) {
        let i = (self.di & 0xFFFF) as usize;
        self.buf[i..i + 4].copy_from_slice(&v.to_le_bytes());
        self.di += 4;
    }
}

/// The header common to the three packets: 0x6A, (extra byte), 0x1C, type, u16, net id, count.
unsafe fn pkt_header(kind: u8, last_u16: u16, veh: u32, count: u32) -> Pkt {
    unsafe {
        let mut p = Pkt { buf: [0; 0x510], di: 0 };
        p.buf[0] = 0x6A;
        p.di = if rb(NET_EXTRA_BYTE) != 0 { 4 } else { 3 };
        p.put8(0x1C);
        p.put8(kind);
        p.put16(last_u16);
        p.put16(veh_net_id(veh));
        p.put32(count);
        p
    }
}

/// Length field, connection lookup and send.
unsafe fn pkt_send(mut p: Pkt, veh: u32, edx_hi: u32) {
    unsafe {
        let len = (p.di.wrapping_sub(3) & 0xFFFF) as u16;
        p.buf[1..3].copy_from_slice(&len.to_le_bytes());
        let conn = if veh == 0 {
            0
        } else {
            let b = rd(veh as usize + 0xB0);
            if b == 0 {
                0
            } else {
                call_regs(FIND_CONN, rd(NET_SESSION), 0, edx_hi | rb(b as usize) as u32, 0, 0, &[])
            }
        };
        call_regs(NET_SEND, 0, 0, 0, conn, 0, &[p.buf.as_ptr() as u32, p.di & 0xFFFF, 0, 0]);
    }
}

// --- 0xB28700 vehicle_ai_pathfind_navmesh (ECX = u32* node pointers; stack: vehicle, count, a3, a4, a5, a6) --
//
// count > 0x19 (signed) -> 0. Remote: packet type 2, flags = (a3 byte != 0 ? 0x20 : 0) | (a4 byte != 0) |
// (a5 byte != 0 ? 4 : 0), then per node the three f32 at [ptr + 0x1C / 0x20 / 0x24]; returns 2. Local:
// order_05(ai = vehicle + 0x8554, nodes, count, &opts {u8 0, u32 a3 != 0, u8 a5, f32 0}), then the goal block
// {flags a4 & 1, pos = last node's three dwords, +0x10 f32 [0xE38AE0], +0x18 f32 [0xE8725C], +0x24 u8 0,
// +0x28.. f32 0} through goal_install(EAX = goal; ai, 1, a6 as a dword) with ECX = a4 & 1; returns 1.

unsafe fn vehicle_ai_pathfind_navmesh(nodes: u32, a: *const u32) -> u32 {
    unsafe {
        let (veh, count) = (*a, *a.add(1) as i32);
        let (a3, a4, a5, a6) = (*a.add(2) as u8, *a.add(3) as u8, *a.add(4) as u8, *a.add(5));
        if count > 0x19 {
            hit(15);
            return 0;
        }
        let local = call_regs(OWNED_LOCALLY, veh, 0, 0, 0, 0, &[]) as u8 != 0;
        if !local {
            hit(13);
            let mut p = pkt_header(2, a6 as u16, veh, count as u32);
            let flags = if a3 != 0 { 0x20 } else { 0 } | (a4 != 0) as u8 | if a5 != 0 { 4 } else { 0 };
            p.put8(flags);
            for k in 0..count.max(0) as usize {
                let ptr = rd(nodes as usize + 4 * k) as usize;
                for o in [0x1Cusize, 0x20, 0x24] {
                    p.put32(quiet(rd(ptr + o)));
                }
            }
            pkt_send(p, veh, veh & !0xFF);
            return 2;
        }
        hit(14);
        let ai = veh.wrapping_add(0x8554);
        let opts: [u32; 4] = [0, (a3 != 0) as u32, a5 as u32, 0];
        call_regs(ORDER_05, 0, 0, 0, 0, 0, &[ai, nodes, count as u32, opts.as_ptr() as u32]);
        let last = rd((nodes as usize).wrapping_add((count as usize).wrapping_mul(4)).wrapping_sub(4)) as usize;
        let mut goal = [0u32; 13];
        goal[0] = (a4 & 1) as u32;
        goal[1] = rd(last + 0x1C);
        goal[2] = rd(last + 0x20);
        goal[3] = rd(last + 0x24);
        goal[4] = quiet(rd(GOAL_F1));
        goal[6] = quiet(rd(GOAL_F2));
        call_regs(GOAL_INSTALL, goal.as_ptr() as u32, (a4 & 1) as u32, 0, 0, 0, &[ai, 1, a6]);
        1
    }
}

extern "C" fn navmesh_entry(r: &mut Pushad, args: *const u32) -> u32 {
    let p = *r;
    r.eax = unsafe { vehicle_ai_pathfind_navmesh(p.ecx, args) };
    0
}
thunk4!(navmesh_thunk, navmesh_entry, eax);

// --- 0xB27D90 vehicle_ai_pathfind_nodes (ECX = vec3* nodes; stack: vehicle, count, a3, a4, a5, a6, a7, f32 a8, a9) --
//
// count must be 2..=0x19 (unsigned `count - 2 <= 0x17`), else 0. Remote: packet type 1, u16 a9, flags
// (a3 byte ? 2) | (a4 byte != 0) | (a5 ? 4) | (a6 ? 0x10) | (a7 ? 8), f32 a8 (quieted), then count x 3 f32
// from `nodes`; returns 2. Local: m = vehicle_nav_query_mask(vehicle); unless a7: nodes[0] = vehicle.pos when
// 0xB264C0(EAX = &pos, EDX = m) says so; otherwise the nearest lane (query block {&pos, m, 0x104, &dir,
// f32 [0xDD0C4C], byte q0 / q1 by 0xAB5340}) gives nodes[0] through spline_eval_position(EAX = lane,
// ESI = nodes, 0.5f); no lane -> 0. Route block {count, nodes, a3 byte, 0, a5 byte, f32 [0xE38AE0] (a8 unless
// a8 < 0), m | 0x8000 when byte [vehicle+0x8566] & 0x20, packed tail}; route = a6 byte ? 0xB269D0(&block)
// : 0xB26570(&block, 0); none -> 0. spline_closest_point(EDI = [[route+4]+0xC], EAX = &nodes[count-1],
// ESI = &out); order_0e(ECX = &{u8 0, 1, 0, 0, route}, ai); a packed-tail flag makes 0xB29940 run with
// EDI = ai; the goal block starts from 0x459110(EAX = &goal), pos = out, flags (init & 0xFE) | (a4 & 1) | 4;
// goal_install(EAX = &goal; ai, 1, a9) with ECX = out.z bits; returns 1.

const NEAREST_LANE_MASK_ADDR: usize = 0x00B2_6530;
const ROUTE_POS_OK: usize = 0x00B2_64C0;
const LANE_CLASS: usize = 0x00AB_5340;
const FIND_LANE: usize = 0x00B1_E950;
const SPLINE_EVAL_POS: usize = 0x00C0_3910;
const ROUTE_BUILD_A: usize = 0x00B2_69D0;
const ROUTE_BUILD_B: usize = 0x00B2_6570;
const SPLINE_CLOSEST: usize = 0x00A1_ED20;
const ORDER_0E: usize = 0x00B6_1180;
const ROUTE_TAIL_FN: usize = 0x00B2_9940;
const GOAL_INIT: usize = 0x0045_9110;
const LANE_QUERY_F: usize = 0x00DD_0C4C;
const HALF_F: usize = 0x00DD_1C8C;

unsafe fn vehicle_ai_pathfind_nodes(nodes: u32, a: *const u32) -> u32 {
    unsafe {
        let (veh, count) = (*a, *a.add(1));
        let (a3, a4, a5, a6, a7) = (*a.add(2) as u8, *a.add(3) as u8, *a.add(4) as u8, *a.add(5) as u8, *a.add(6) as u8);
        let (a8, a9) = (*a.add(7), *a.add(8));
        if count.wrapping_sub(2) > 0x17 {
            hit(18);
            return 0;
        }
        let local = call_regs(OWNED_LOCALLY, veh, 0, 0, 0, 0, &[]) as u8 != 0;
        if !local {
            hit(16);
            let mut p = pkt_header(1, a9 as u16, veh, count);
            let flags = if a3 != 0 { 2 } else { 0 } | (a4 != 0) as u8 | if a5 != 0 { 4 } else { 0 } | if a6 != 0 { 0x10 } else { 0 } | if a7 != 0 { 8 } else { 0 };
            p.put8(flags);
            p.put32(quiet(a8));
            for k in 0..count as usize * 3 {
                p.put32(quiet(rd(nodes as usize + 4 * k)));
            }
            pkt_send(p, veh, veh & !0xFF);
            return 2;
        }
        hit(17);
        let m = call_regs(NEAREST_LANE_MASK_ADDR, veh, 0, 0, 0, 0, &[]);
        let vp = veh as usize;
        let mut have_pos = false;
        if a7 == 0 && call_regs(ROUTE_POS_OK, veh.wrapping_add(0x14), 0, m, 0, 0, &[]) as u8 != 0 {
            for k in 0..3 {
                wd(nodes as usize + 4 * k, rd(vp + 0x14 + 4 * k));
            }
            have_pos = true;
        }
        if !have_pos {
            let mut q = [0u32; 7];
            q[0] = veh.wrapping_add(0x14);
            q[1] = m;
            q[2] = 0x104;
            q[3] = veh.wrapping_add(0x38);
            q[4] = quiet(rd(LANE_QUERY_F));
            let b = if call_regs(LANE_CLASS, veh, 0, 0, 0, 0, &[]) as u8 != 0 { 0x0100u32 } else { 0x0001 };
            q[6] = b;
            let lane = call_regs(FIND_LANE, q.as_ptr() as u32, 0, 0, 0, 0, &[]);
            if lane == 0 {
                return 0;
            }
            call_regs(SPLINE_EVAL_POS, lane, 0, 0, nodes, 0, &[quiet(rd(HALF_F))]);
        }
        // the route query block (0x24 bytes: u32 count, nodes, u8 a3, u32 0, u8 a5, f32, u32 mask, packed tail)
        let mut blk = [0u8; 0x24];
        blk[0..4].copy_from_slice(&count.to_le_bytes());
        blk[4..8].copy_from_slice(&nodes.to_le_bytes());
        blk[8] = a3;
        blk[0x10] = a5;
        let f = if !(f32::from_bits(a8) >= 0.0) { quiet(rd(GOAL_F1)) } else { quiet(a8) };
        blk[0x14..0x18].copy_from_slice(&f.to_le_bytes());
        let mask = m | if rb(vp + 0x8566) & 0x20 != 0 { 0x8000 } else { 0 };
        blk[0x18..0x1C].copy_from_slice(&mask.to_le_bytes());
        let bp = blk.as_ptr() as u32;
        let route = if a6 != 0 { call_regs(ROUTE_BUILD_A, 0, 0, 0, 0, 0, &[bp]) } else { call_regs(ROUTE_BUILD_B, 0, 0, 0, 0, 0, &[bp, 0]) };
        if route == 0 {
            return 0;
        }
        let r4 = rd(route as usize + 4) as usize;
        let mut out = [0f32; 3];
        let last = nodes.wrapping_add(count.wrapping_mul(12)).wrapping_sub(12);
        call_st0(SPLINE_CLOSEST, last, 0, 0, out.as_mut_ptr() as u32, rd(r4 + 0xC), &[]);
        let ai = veh.wrapping_add(0x8554);
        let tmp: [u32; 5] = [0, 1, 0, 0, route];
        call_regs(ORDER_0E, 0, tmp.as_ptr() as u32, 0, 0, 0, &[ai]);
        // (ESI is &out and EDI the original's register here; order_0e reads neither)
        if blk[0x1C] != 0 {
            let d1 = u32::from_le_bytes(blk[0x1D..0x21].try_into().unwrap());
            let d2 = u32::from_le_bytes(blk[0x20..0x24].try_into().unwrap());
            call_regs(ROUTE_TAIL_FN, 0, 0, 0, 0, ai, &[d2, rd(route as usize + 0xC), d1]);
        }
        let mut goal = [0u32; 13];
        call_regs(GOAL_INIT, goal.as_mut_ptr() as u32, 0, 0, 0, 0, &[]);
        goal[1] = out[0].to_bits();
        goal[2] = out[1].to_bits();
        goal[3] = out[2].to_bits();
        goal[0] = (goal[0] as u8 & 0xFE | (a4 & 1) | 4) as u32 | (goal[0] & !0xFF);
        call_regs(GOAL_INSTALL, goal.as_ptr() as u32, out[2].to_bits(), 0, 0, 0, &[ai, 1, a9]);
        1
    }
}

extern "C" fn nodes_entry(r: &mut Pushad, args: *const u32) -> u32 {
    let p = *r;
    r.eax = unsafe { vehicle_ai_pathfind_nodes(p.ecx, args) };
    0
}
thunk4!(nodes_thunk, nodes_entry, eax);

// --- 0xB27830 vehicle_ai_pathfind_to (ECX = vehicle; stack: nodes, count, a3, a4, a5, f32 a6, a7) -------------
//
// count > 0x19 (signed) -> 0. Remote: packet type 0, u16 a7, flags (a3 byte != 0) | (a4 byte ? 2) |
// (a5 byte ? 4), f32 a6 (quieted), count x 3 f32 from `nodes`; returns 2. Local: r = 0xB21F70(ECX = vehicle)
// (a pointer or 0), m = vehicle_nav_query_mask. r != 0: the lane slot is r and nodes[0] = vehicle.pos. Else
// the nearest lane (query block as in _nodes, byte q at +0x18 / +0x19): found, or 0xB264C0(EAX = &pos,
// EDX = m) true -> nodes[0] = vehicle.pos with lane 0 (a found lane's position is not copied: the lane
// slot is the lane); else 0xB1E2C0(ECX = m, EDX = 0; &pos, f32 [0xE1D904]) must give a spline (none -> 0),
// spline_eval_position(EAX = it, ESI = nodes, 0.5f) and usedClosest = 1, lane slot 0. Route block {count,
// nodes, u8 a4, lane slot, u8 a5, f32 [0xE38AE0] (a6 when a6 >= 0), mask m, packed tail}; route = 0xB26570(
// &block, 0) (none -> 0); spline_closest_point(EDI = [[route+4]+0xC], EAX = &nodes[count-1], ESI = &out);
// usedClosest ? 0xB5FB30(ECX = route; ai, 0) : 0xB55950(ECX = route, ESI = [route+0xC]; ai) and, with the
// tail flag, 0xB29940(EDI = ai; dword@+0x20, [route+0xC], dword@+0x1D); goal {flags (a3 & 1) | 4, pos = out,
// f32 [0xE38AE0] / [0xE8725C], ...} through goal_install(EAX = &goal; ai, 1, a7 dword) with
// ECX = (out.z & !0xFF) | (a3 & 1); returns 1.

const OWNED_ROUTE_FN: usize = 0x00B2_1F70;
const CLOSEST_LANE_FN: usize = 0x00B1_E2C0;
const ORDER_0D: usize = 0x00B5_FB30;
const ORDER_09: usize = 0x00B5_5950;
const CLOSEST_LANE_F: usize = 0x00E1_D904;

unsafe fn vehicle_ai_pathfind_to(veh: u32, a: *const u32) -> u32 {
    unsafe {
        let (nodes, count) = (*a, *a.add(1) as i32);
        let (a3, a4, a5) = (*a.add(2) as u8, *a.add(3) as u8, *a.add(4) as u8);
        let (a6, a7) = (*a.add(5), *a.add(6));
        if count > 0x19 {
            hit(21);
            return 0;
        }
        let local = call_regs(OWNED_LOCALLY, veh, 0, 0, 0, 0, &[]) as u8 != 0;
        if !local {
            hit(19);
            let mut p = pkt_header(0, a7 as u16, veh, count as u32);
            let flags = (a3 != 0) as u8 | if a4 != 0 { 2 } else { 0 } | if a5 != 0 { 4 } else { 0 };
            p.put8(flags);
            p.put32(quiet(a6));
            for k in 0..count.max(0) as usize * 3 {
                p.put32(quiet(rd(nodes as usize + 4 * k)));
            }
            pkt_send(p, veh, 0); // _to: EDX is the movzx'd packet offset, DL the conn id byte
            return 2;
        }
        hit(20);
        let vp = veh as usize;
        let r = call_regs(OWNED_ROUTE_FN, 0, veh, 0, 0, 0, &[]);
        let m = call_regs(NEAREST_LANE_MASK_ADDR, veh, 0, 0, 0, 0, &[]);
        let mut used_closest = false;
        let lane_slot: u32;
        let mut copy_pos = true;
        if r != 0 {
            lane_slot = r;
        } else {
            let mut q = [0u32; 7];
            q[0] = veh.wrapping_add(0x14);
            q[1] = m;
            q[2] = 0x104;
            q[3] = veh.wrapping_add(0x38);
            q[4] = quiet(rd(LANE_QUERY_F));
            q[6] = if call_regs(LANE_CLASS, veh, 0, 0, 0, 0, &[]) as u8 != 0 { 0x0100 } else { 0x0001 };
            let lane = call_regs(FIND_LANE, q.as_ptr() as u32, 0, 0, 0, 0, &[]);
            if lane != 0 {
                lane_slot = lane;
            } else if call_regs(ROUTE_POS_OK, veh.wrapping_add(0x14), 0, m, 0, 0, &[]) as u8 != 0 {
                lane_slot = 0;
            } else {
                let sp = call_regs(CLOSEST_LANE_FN, 0, m, 0, 0, 0, &[veh.wrapping_add(0x14), quiet(rd(CLOSEST_LANE_F))]);
                used_closest = true;
                if sp == 0 {
                    return 0;
                }
                call_regs(SPLINE_EVAL_POS, sp, 0, 0, nodes, 0, &[quiet(rd(HALF_F))]);
                lane_slot = 0;
                copy_pos = false;
            }
        }
        if copy_pos {
            for k in 0..3 {
                wd(nodes as usize + 4 * k, rd(vp + 0x14 + 4 * k));
            }
        }
        let mut blk = [0u8; 0x24];
        blk[0..4].copy_from_slice(&(count as u32).to_le_bytes());
        blk[4..8].copy_from_slice(&nodes.to_le_bytes());
        blk[8] = a4;
        blk[0xC..0x10].copy_from_slice(&lane_slot.to_le_bytes());
        blk[0x10] = a5;
        let f = if !(f32::from_bits(a6) >= 0.0) { quiet(rd(GOAL_F1)) } else { quiet(a6) };
        blk[0x14..0x18].copy_from_slice(&f.to_le_bytes());
        blk[0x18..0x1C].copy_from_slice(&m.to_le_bytes());
        let bp = blk.as_ptr() as u32;
        let route = call_regs(ROUTE_BUILD_B, 0, 0, 0, 0, 0, &[bp, 0]);
        if route == 0 {
            return 0;
        }
        let r4 = rd(route as usize + 4) as usize;
        let mut out = [0f32; 3];
        let last = nodes.wrapping_add((count as u32).wrapping_mul(12)).wrapping_sub(12);
        call_st0(SPLINE_CLOSEST, last, 0, 0, out.as_mut_ptr() as u32, rd(r4 + 0xC), &[]);
        let ai = veh.wrapping_add(0x8554);
        if used_closest {
            call_regs(ORDER_0D, 0, route, 0, 0, ai, &[ai, 0]);
        } else {
            let rc = rd(route as usize + 0xC);
            call_regs(ORDER_09, 0, route, 0, rc, ai, &[ai]);
            if blk[0x1C] != 0 {
                let d1 = u32::from_le_bytes(blk[0x1D..0x21].try_into().unwrap());
                let d2 = u32::from_le_bytes(blk[0x20..0x24].try_into().unwrap());
                call_regs(ROUTE_TAIL_FN, 0, 0, 0, rc, ai, &[d2, rc, d1]);
            }
        }
        let mut goal = [0u32; 13];
        goal[0] = ((a3 & 1) | 4) as u32;
        goal[1] = out[0].to_bits();
        goal[2] = out[1].to_bits();
        goal[3] = out[2].to_bits();
        goal[4] = quiet(rd(GOAL_F1));
        goal[6] = quiet(rd(GOAL_F2));
        call_regs(GOAL_INSTALL, goal.as_ptr() as u32, (out[2].to_bits() & !0xFF) | (a3 & 1) as u32, 0, 0, 0, &[ai, 1, a7]);
        1
    }
}

extern "C" fn to_entry(r: &mut Pushad, args: *const u32) -> u32 {
    let p = *r;
    r.eax = unsafe { vehicle_ai_pathfind_to(p.ecx, args) };
    0
}
thunk4!(to_thunk, to_entry, eax);
