pub fn install() {
    if !unsafe { consts_ok() } {
        log("port_nav2: constants differ from the decoded build, nothing replaced");
        return;
    }
    // (port, original body, its call offsets, thunk)
    let list: [(usize, &[u8], &[usize], usize); COUNT] = [
        (P_RQ, &RQ_SETUP_BODY, &RQ_SETUP_BODY_CALLS, rq_setup_thunk as *const () as usize),
        (P_MID, &MID_BODY, &MID_BODY_CALLS, mid_thunk as *const () as usize),
        (P_HEUR, &HEUR_BODY, &HEUR_BODY_CALLS, heur_thunk as *const () as usize),
        (P_LINK, &LINK_BODY, &LINK_BODY_CALLS, link_thunk as *const () as usize),
        (P_POP, &POP_BODY, &POP_BODY_CALLS, pop_thunk as *const () as usize),
        (P_SIFT_UP, &SIFT_UP_BODY, &SIFT_UP_BODY_CALLS, sift_up_thunk as *const () as usize),
        (P_VCLEAR, &VCLEAR_BODY, &VCLEAR_BODY_CALLS, vclear_thunk as *const () as usize),
        (P_REACH, &REACH_BODY, &REACH_BODY_CALLS, reach_thunk as *const () as usize),
        (P_NAVMESH, &NAVMESH_BODY, &NAVMESH_BODY_CALLS, navmesh_thunk as *const () as usize),
        (P_NODES, &NODES_BODY, &NODES_BODY_CALLS, nodes_thunk as *const () as usize),
        (P_TO, &TO_BODY, &TO_BODY_CALLS, to_thunk as *const () as usize),
    ];
    let mut ok = 0;
    for (id, body, calls, thunk) in list {
        let pt = &PORTS[id];
        if pt.window > 0 {
            // The shadow copy first: replacing patches the entry.
            match unsafe { detour::relocate(pt.addr, body, calls) } {
                Ok(copy) => pt.original.store(copy, Ordering::Relaxed),
                Err(e) => log(&format!("port_nav2: {}: no shadow copy: {e:?}", pt.name)),
            }
        }
        if replace_pinned(pt.name, pt.addr, body, thunk) {
            ok += 1;
        }
    }
    log(&format!("port_nav2: replaced {ok}/{COUNT} with Rust"));
}

const HIT_NAMES: [(usize, &str); 22] = [(0, "rq_no_net"), (1, "rq_no_tree"), (2, "rq_walk"), (3, "reach_popped_goal"), (4, "reach_nb_goal"), (5, "reach_relax_full"), (6, "reach_drained"), (7, "reach_seed_fail"), (8, "pop_empty"), (9, "pop_single"), (10, "pop_multi"), (11, "sift_up_out_of_range"), (12, "sift_up_moved"), (13, "veh_remote_packet"), (14, "veh_local_order"), (15, "veh_reject_count"), (16, "nodes_remote_packet"), (17, "nodes_local_order"), (18, "nodes_reject_count"), (19, "to_remote_packet"), (20, "to_local_order"), (21, "to_reject_count")];

/// Per-function call counts for the periodic log.
pub fn summary() -> String {
    let mut parts: Vec<String> = PORTS
        .iter()
        .filter_map(|p| {
            let c = p.calls.load(Ordering::Relaxed);
            (c > 0).then(|| format!("{} {c} ({} shadow mismatches)", p.name, p.mismatches.load(Ordering::Relaxed)))
        })
        .collect();
    for (i, n) in HIT_NAMES {
        let h = HITS[i].load(Ordering::Relaxed);
        if h > 0 {
            parts.push(format!("{n} {h}"));
        }
    }
    if parts.is_empty() {
        return String::new();
    }
    format!("port_nav2: {}", parts.join(", "))
}
#[cfg(test)]
#[allow(dead_code)]
pub(crate) mod dt {
    use std::cell::{Cell, RefCell};
    use std::ffi::c_void;
    use windows_sys::Win32::System::Memory::{MEM_COMMIT, MEM_RESERVE, PAGE_EXECUTE_READWRITE, VirtualAlloc};

    pub const EAX: u8 = 1;
    pub const ECX: u8 = 2;
    pub const EDX: u8 = 4;
    pub const ESI: u8 = 8;
    pub const EDI: u8 = 16;

    /// Where a callee's result comes from.
    #[derive(Clone, Copy, PartialEq)]
    pub enum Ret {
        /// Nothing in EAX that matters (a random value comes back anyway).
        Any,
        /// A flag: 0, 1, 0x100 (AL clear but EAX not), or random.
        Bool,
        /// 0 or a member of pool `n`.
        Ptr(usize),
        /// Always 0.
        Zero,
        /// Always a member of pool `n`.
        PtrNz(usize),
        /// Returns a double on the x87 stack (and a random value in EAX).
        St0,
        /// A random value below `n`.
        Mod(u32),
        /// EAX comes back unchanged (the /GS cookie check).
        Keep,
        /// EAX comes back as the ECX the callee got.
        Ecx,
        /// EAX comes back as the ESI the callee got.
        Esi,
    }

    /// What a callee does besides returning.
    #[derive(Clone, Copy, PartialEq)]
    pub enum Fx {
        None,
        /// Writes a random u32 at [ESI] (the xtbl getters).
        WriteUint,
        /// Writes a random f32 at [ESI].
        WriteFloat,
        /// Logs the bytes of a buffer: `args[0]` pointer, `args[1]` length (byte 3 masked when the
        /// length is 9: the original leaves it unwritten).
        LogBuf,
        /// Logs `ECX * 3` dwords at [EDX] (a vector list).
        LogVec,
        /// Logs the three bytes at [EDX].
        LogEdx3,
        /// Logs `n` dwords at the pointer in `args[0]`.
        LogArg0(usize),
        /// Logs `n` bytes at the pointer in EAX.
        LogEaxBytes(usize),
        /// Removes one handle record from the player's pending list (args: player, object).
        RemoveListEntry,
        /// Writes random floats through the two pointer arguments (3 and 9 dwords).
        FillOut2,
        /// Logs 0x5C bytes at [EAX] and writes three random dwords at [ECX].
        Vec465,
        /// Writes three random dwords at [ESI].
        Out3Esi,
        /// Writes three random floats through the first stack argument.
        WriteVecArg0,
        /// Writes nine random floats at [EAX].
        Fill9Eax,
        /// 0x9A1970's outputs: three floats at each of the two pointers, a flag byte at the third.
        Fill1970,
        /// Logs what 0x9A2670 reads: 3 dwords at each of the first two pointers, the byte at the third.
        Log2670,
        /// Logs the dword at [ESI].
        LogEsi1,
        /// Sets the open-heap count to 1..4 (a relax that queued a cell).
        HeapCnt,
        /// Logs byte ranges (offset, length) at the pointer in stack argument `n`.
        LogArgMem(usize, &'static [(usize, usize)]),
        /// Logs byte ranges (offset, length) at the pointer in EAX.
        LogEaxMem(&'static [(usize, usize)]),
        /// Logs byte ranges at the pointer in ECX.
        LogEcxMem(&'static [(usize, usize)]),
        /// A route query block in arg 0: logs its inputs, then fills the packed tail at +0x1C..+0x23.
        RouteBlock,
        /// Zeroes `n` bytes at [EAX] (a block initialiser).
        ZeroEax(usize),
    }

    #[derive(Clone)]
    pub struct Callee {
        pub target: usize,
        pub nargs: usize,
        pub pop: usize,
        /// Registers the callee reads on entry (the only ones compared).
        pub reads: u8,
        pub ret: Ret,
        pub fx: Fx,
        pub silent: bool,
        /// Stack arguments the callee reads as one byte (the caller leaves stale upper bits).
        pub byte_args: u32,
        /// Registers the callee reads as one byte (the caller leaves stale upper bits).
        pub byte_regs: u8,
        /// Registers the callee reads as 16 bits.
        pub word_regs: u8,
        /// A native replacement the original's call is aimed at (0: the recording stub).
        pub native: usize,
    }

    pub fn callee(target: usize, nargs: usize, pop: usize, reads: u8, ret: Ret, fx: Fx) -> Callee {
        Callee { target, nargs, pop, reads, ret, fx, silent: false, byte_args: 0, byte_regs: 0, word_regs: 0, native: 0 }
    }

    /// Prints what already occupies the address space the game's globals need.
    pub fn dump_occupied() {
        use windows_sys::Win32::System::Memory::{MEMORY_BASIC_INFORMATION, MEM_FREE, VirtualQuery};
        let mut a = 0x40_0000usize;
        while a < 0x400_0000 {
            let mut m: MEMORY_BASIC_INFORMATION = unsafe { std::mem::zeroed() };
            if unsafe { VirtualQuery(a as *const c_void, &mut m, std::mem::size_of::<MEMORY_BASIC_INFORMATION>()) } == 0 {
                break;
            }
            if m.State != MEM_FREE {
                eprintln!("occupied {:#x}..{:#x} state {:#x} type {:#x}", m.BaseAddress as usize, m.BaseAddress as usize + m.RegionSize, m.State, m.Type);
            }
            a = m.BaseAddress as usize + m.RegionSize;
        }
    }

    pub struct Rng(pub u64);
    impl Rng {
        pub fn u32(&mut self) -> u32 {
            self.0 ^= self.0 << 13;
            self.0 ^= self.0 >> 7;
            self.0 ^= self.0 << 17;
            (self.0 >> 16) as u32
        }
        pub fn below(&mut self, n: u32) -> u32 {
            self.u32() % n
        }
        /// True once in `n`.
        pub fn one_in(&mut self, n: u32) -> bool {
            self.below(n) == 0
        }
        /// One of `v`, or (one time in four) a random value below `modulus` (any u32 when 0).
        pub fn mix(&mut self, v: &[u32], modulus: u32) -> u32 {
            if self.below(4) == 0 {
                let r = self.u32();
                if modulus == 0 { r } else { r % modulus }
            } else {
                self.pick(v)
            }
        }
        pub fn pick<T: Copy>(&mut self, v: &[T]) -> T {
            v[self.below(v.len() as u32) as usize]
        }
        /// A float bit pattern with the awkward cases over-represented.
        pub fn float_bits(&mut self) -> u32 {
            match self.below(12) {
                0 => 0,
                1 => 0x8000_0000,
                2 => 0x3F80_0000,
                3 => 0xBF80_0000,
                4 => 0x7FC0_0000,
                5 => 0x7F80_0001, // signalling NaN
                6 => 0x7F80_0000,
                7 => 0x0000_0001, // denormal
                8 => (self.below(2000) as f32 / 1000.0 - 0.5).to_bits(),
                9 => (self.below(20000) as f32 / 10.0).to_bits(),
                _ => self.u32(),
            }
        }
    }

    pub fn fixed(addr: usize, len: usize) {
        let mut p = unsafe { VirtualAlloc(addr as *const c_void, len, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE) };
        if p.is_null() {
            p = unsafe { VirtualAlloc(addr as *const c_void, len, MEM_COMMIT, PAGE_EXECUTE_READWRITE) };
        }
        assert_eq!(p as usize, addr, "cannot map {addr:#x}: error {}", unsafe { windows_sys::Win32::Foundation::GetLastError() });
    }

    /// The fixed regions the original touches: snapshotted, restored and compared as one.
    pub struct Mem {
        pub regions: Vec<(usize, usize)>,
    }

    impl Mem {
        /// Regions: every absolute address in `body` that falls in the game's data range (moved by
        /// `DELTA`), plus `extra` (game addresses), plus the arena; all rounded out to 64 KB.
        pub fn new(body: &[u8], extra: &[(usize, usize)]) -> Mem {
            let mut spans: Vec<(usize, usize)> = extra.iter().map(|&(a, l)| (super::tr(a), l)).collect();
            for i in 0..body.len().saturating_sub(3) {
                let v = u32::from_le_bytes([body[i], body[i + 1], body[i + 2], body[i + 3]]) as usize;
                if (0xD0_0000..0x350_0000).contains(&v) {
                    spans.push((super::tr(v), 1));
                }
            }
            spans.push((ARENA, ARENA_LEN));
            let mut pages: Vec<usize> = Vec::new();
            for (a, l) in spans {
                let mut p = a & !0xFFFF;
                while p < a + l {
                    pages.push(p);
                    p += 0x1_0000;
                }
            }
            pages.sort_unstable();
            pages.dedup();
            let mut regions: Vec<(usize, usize)> = Vec::new();
            for p in pages {
                match regions.last_mut() {
                    Some(r) if r.0 + r.1 == p => r.1 += 0x1_0000,
                    _ => regions.push((p, 0x1_0000)),
                }
            }
            for &(a, l) in &regions {
                fixed(a, l);
            }
            Mem { regions }
        }

        pub fn fill_random(&self, rng: &mut Rng) {
            for &(a, l) in &self.regions {
                let s = unsafe { std::slice::from_raw_parts_mut(a as *mut u32, l / 4) };
                for w in s.iter_mut() {
                    *w = rng.u32();
                }
            }
        }

        /// Zero `l` bytes at the game address `a`.
        pub fn zero(&self, a: usize, l: usize) {
            unsafe { std::ptr::write_bytes(super::tr(a) as *mut u8, 0, l) };
        }

        pub fn snapshot(&self) -> Vec<u8> {
            let mut v = Vec::new();
            for &(a, l) in &self.regions {
                v.extend_from_slice(unsafe { std::slice::from_raw_parts(a as *const u8, l) });
            }
            v
        }

        pub fn restore(&self, snap: &[u8]) {
            let mut at = 0;
            for &(a, l) in &self.regions {
                unsafe { std::ptr::copy_nonoverlapping(snap[at..at + l].as_ptr(), a as *mut u8, l) };
                at += l;
            }
        }

        /// The first difference between two snapshots, as an address.
        pub fn first_diff(&self, a: &[u8], b: &[u8]) -> Option<(usize, u8, u8)> {
            let mut at = 0;
            for &(base, l) in &self.regions {
                for i in 0..l {
                    if a[at + i] != b[at + i] {
                        return Some((base + i, a[at + i], b[at + i]));
                    }
                }
                at += l;
            }
            None
        }

        pub fn count_diffs(&self, a: &[u8], b: &[u8]) -> usize {
            a.iter().zip(b).filter(|(x, y)| x != y).count()
        }
    }

    #[repr(C)]
    pub struct Pushad {
        edi: u32,
        esi: u32,
        ebp: u32,
        esp: u32,
        ebx: u32,
        edx: u32,
        ecx: u32,
        eax: u32,
    }

    thread_local! {
        static CALLEES: RefCell<Vec<Callee>> = const { RefCell::new(Vec::new()) };
        static STUBS: RefCell<Vec<usize>> = const { RefCell::new(Vec::new()) };
        static POOLS: RefCell<Vec<Vec<u32>>> = const { RefCell::new(Vec::new()) };
        static LOG: RefCell<Vec<Vec<u32>>> = const { RefCell::new(Vec::new()) };
        static SRNG: Cell<u64> = const { Cell::new(1) };
    }

    pub fn set_pools(p: Vec<Vec<u32>>) {
        POOLS.with(|x| *x.borrow_mut() = p);
    }

    /// The address a call to `f` should really go to: its stub when it has one.
    pub fn redirect(f: usize) -> usize {
        CALLEES.with(|c| {
            let c = c.borrow();
            match c.iter().position(|x| x.target == f) {
                Some(i) if c[i].native != 0 => c[i].native,
                Some(i) => STUBS.with(|s| s.borrow()[i]),
                None => f,
            }
        })
    }

    /// Adds a line to the recorded call log (for natives that stand in for a callee).
    pub fn push_log(e: Vec<u32>) {
        LOG.with(|l| l.borrow_mut().push(e));
    }

    /// The next number of the stubs' random stream.
    pub fn rand_u32() -> u32 {
        srng()
    }

    fn srng() -> u32 {
        SRNG.with(|s| {
            let mut r = Rng(s.get());
            let v = r.u32();
            s.set(r.0);
            v
        })
    }

    extern "C" fn stub_rs(regs: *mut Pushad, idx: u32, args: *const u32) -> u32 {
        let c = CALLEES.with(|c| c.borrow()[idx as usize].clone());
        let r = unsafe { &*regs };
        if TRACE.load(std::sync::atomic::Ordering::Relaxed) {
            eprintln!("stub {:#x} eax {:#x} ecx {:#x} edx {:#x} esi {:#x} edi {:#x} a0 {:#x} a1 {:#x}", c.target, r.eax, r.ecx, r.edx, r.esi, r.edi, unsafe { *args }, unsafe { *args.add(1) });
        }
        // Pointers into the stack differ between the two runs: log a marker for them.
        let mask = |v: u32| if (STACK..STACK + STACK_LEN).contains(&(v as usize)) { 0x57AC_0000 } else { v };
        if !c.silent {
            let mut e = vec![c.target as u32];
            for (bit, v) in [(EAX, r.eax), (ECX, r.ecx), (EDX, r.edx), (ESI, r.esi), (EDI, r.edi)] {
                e.push(if c.reads & bit == 0 { 0 } else if c.byte_regs & bit != 0 { v & 0xFF } else if c.word_regs & bit != 0 { v & 0xFFFF } else { mask(v) });
            }
            for k in 0..c.nargs {
                let v = unsafe { *args.add(k) };
                e.push(if c.byte_args >> k & 1 != 0 { v & 0xFF } else { mask(v) });
            }
            match c.fx {
                Fx::LogVec => {
                    for k in 0..(r.ecx.min(40) * 3) as usize {
                        e.push(mask(unsafe { *((r.edx as usize + k * 4) as *const u32) }));
                    }
                }
                Fx::LogArgMem(n, rs) => {
                    let p = unsafe { *args.add(n) } as usize;
                    for &(o, l) in rs {
                        for k in 0..l {
                            e.push(unsafe { *((p + o + k) as *const u8) } as u32);
                        }
                    }
                }
                Fx::LogEcxMem(rs) => {
                    for &(o, l) in rs {
                        for k in 0..l {
                            e.push(unsafe { *((r.ecx as usize + o + k) as *const u8) } as u32);
                        }
                    }
                }
                Fx::RouteBlock => {
                    let p = unsafe { *args } as usize;
                    for &(o, l) in &[(0usize, 4usize), (4, 4), (8, 1), (0xC, 4), (0x10, 1), (0x14, 4), (0x18, 4)] {
                        for k in 0..l {
                            e.push(unsafe { *((p + o + k) as *const u8) } as u32);
                        }
                    }
                }
                Fx::LogEaxMem(rs) => {
                    for &(o, l) in rs {
                        for k in 0..l {
                            e.push(unsafe { *((r.eax as usize + o + k) as *const u8) } as u32);
                        }
                    }
                }
                Fx::LogEsi1 => e.push(unsafe { *(r.esi as usize as *const u32) }),
                Fx::Log2670 => {
                    let (p0, p1, p2) = unsafe { (*args as usize, *args.add(1) as usize, *args.add(2) as usize) };
                    for k in 0..3usize {
                        e.push(unsafe { *((p0 + k * 4) as *const u32) });
                        e.push(unsafe { *((p1 + k * 4) as *const u32) });
                    }
                    e.push(unsafe { *(p2 as *const u8) } as u32);
                }
                Fx::Vec465 => {
                    for k in 0..0x5Cusize {
                        e.push(unsafe { *((r.eax as usize + k) as *const u8) } as u32);
                    }
                }
                Fx::LogEdx3 => {
                    for k in 0..3usize {
                        e.push(unsafe { *((r.edx as usize + k) as *const u8) } as u32);
                    }
                }
                Fx::LogEaxBytes(n) => {
                    for k in 0..n {
                        e.push(unsafe { *((r.eax as usize + k) as *const u8) } as u32);
                    }
                }
                Fx::LogArg0(n) => {
                    let p = unsafe { *args } as usize;
                    for k in 0..n {
                        e.push(mask(unsafe { *((p + k * 4) as *const u32) }));
                    }
                }
                _ => {}
            }
            if c.fx == Fx::LogBuf {
                let (p, len) = unsafe { (*args as usize, *args.add(1) as usize) };
                assert!(len < 512, "LogBuf: callee {:#x} len {len:#x} ptr {p:#x}", c.target);
                for k in 0..len {
                    let mut b = unsafe { *((p + k) as *const u8) };
                    if (len == 9 || len == 7) && k == 3 {
                        b = 0;
                    }
                    e.push(b as u32);
                }
            }
            LOG.with(|l| l.borrow_mut().push(e));
        }
        if c.fx == Fx::RemoveListEntry {
            unsafe {
                let p = *args as usize;
                let o = *args.add(1);
                let cnt = *((p + 0xC3C) as *const u32) as usize;
                if cnt > 0 && cnt < 64 {
                    let obj_of = |h: u32| -> u32 {
                        if h == 0 {
                            return 0;
                        }
                        let e = *(super::tr(0x0214_9C64 + (((h & 0xFFF) as usize) << 4)) as *const u32);
                        if e != 0 && *((e as usize + 0x44) as *const u32) == h { e } else { 0 }
                    };
                    let hk = |k: usize| *((p + 0xC40 + k * 0x18) as *const u32);
                    let mut sel = None;
                    if o != 0 {
                        sel = (0..cnt).find(|&k| obj_of(hk(k)) == o);
                    }
                    if sel.is_none() {
                        sel = (0..cnt).find(|&k| obj_of(hk(k)) == 0);
                    }
                    let j = sel.unwrap_or(0);
                    for k in j..cnt - 1 {
                        std::ptr::copy((p + 0xC40 + (k + 1) * 0x18) as *const u8, (p + 0xC40 + k * 0x18) as *mut u8, 0x18);
                    }
                    *((p + 0xC3C) as *mut u32) = (cnt - 1) as u32;
                }
            }
        }
        match c.fx {
            Fx::RouteBlock => unsafe {
                let mut rng = Rng(srng() as u64 | 1 << 40);
                let p = *args as usize;
                *((p + 0x1C) as *mut u8) = rng.pick(&[0u8, 1, 1]);
                for k in 0..7 {
                    *((p + 0x1D + k) as *mut u8) = rng.u32() as u8;
                }
            },
            Fx::ZeroEax(n) => unsafe {
                std::ptr::write_bytes(r.eax as usize as *mut u8, 0, n);
            },
            Fx::HeapCnt => unsafe {
                *(super::tr(0x2E2E_0C4) as *mut u32) = 1 + srng() % 4;
            },
            Fx::WriteUint => {
                let v = match srng() % 6 {
                    0 => 0,
                    1 => srng() % 10,
                    2 => srng() % 100,
                    3 => srng() % 5000,
                    4 => 0x7FFF_FFFF,
                    _ => srng(),
                };
                unsafe { *(super::tr(r.esi as usize) as *mut u32) = v };
            }
            Fx::FillOut2 => unsafe {
                let mut rng = Rng(srng() as u64 | 1 << 40);
                let (p0, p1) = (*args as usize, *args.add(1) as usize);
                for k in 0..3 {
                    *((p0 + k * 4) as *mut u32) = rng.float_bits();
                }
                for k in 0..9 {
                    *((p1 + k * 4) as *mut u32) = rng.float_bits();
                }
            },
            Fx::Vec465 => unsafe {
                let mut rng = Rng(srng() as u64 | 1 << 40);
                for k in 0..3 {
                    *((r.ecx as usize + k * 4) as *mut u32) = rng.float_bits();
                }
            },
            Fx::Fill9Eax => unsafe {
                let mut rng = Rng(srng() as u64 | 1 << 40);
                for k in 0..9 {
                    *((r.eax as usize + k * 4) as *mut u32) = rng.float_bits();
                }
            },
            Fx::Fill1970 => unsafe {
                let mut rng = Rng(srng() as u64 | 1 << 40);
                let (p1, p2, p3) = (*args.add(1) as usize, *args.add(2) as usize, *args.add(3) as usize);
                for k in 0..3 {
                    *((p1 + k * 4) as *mut u32) = rng.float_bits();
                    *((p2 + k * 4) as *mut u32) = rng.float_bits();
                }
                *(p3 as *mut u8) = rng.pick(&[0u8, 1, 1, 2]);
            },
            Fx::WriteVecArg0 => unsafe {
                let mut rng = Rng(srng() as u64 | 1 << 40);
                let p0 = *args as usize;
                for k in 0..3 {
                    *((p0 + k * 4) as *mut u32) = rng.float_bits();
                }
            },
            Fx::Out3Esi => unsafe {
                let mut rng = Rng(srng() as u64 | 1 << 40);
                for k in 0..3 {
                    *((r.esi as usize + k * 4) as *mut u32) = rng.float_bits();
                }
            },
            Fx::WriteFloat => {
                let mut rng = Rng(srng() as u64 | 1 << 40);
                unsafe { *(super::tr(r.esi as usize) as *mut u32) = rng.float_bits() };
            }
            _ => {}
        }
        match c.ret {
            Ret::Zero => 0,
            Ret::Mod(n) => srng() % n,
            Ret::Keep => r.eax,
            Ret::Ecx => r.ecx,
            Ret::Esi => r.esi,
            Ret::Any => srng(),
            Ret::St0 => {
                let v = match srng() % 8 {
                    0 => 0.0,
                    1 => f32::from_bits(srng()) as f64,
                    2 => srng() as f64 / 7.0,
                    3 => (srng() % 5000) as f64 / 10.0,
                    4 => f64::from_bits((srng() as u64) << 32 | srng() as u64),
                    5 => 1000.0,
                    _ => (srng() % 100) as f64,
                };
                unsafe { ST0V = v };
                srng()
            }
            Ret::PtrNz(n) => POOLS.with(|p| {
                let p = p.borrow();
                let pool = &p[n];
                pool[srng() as usize % pool.len()]
            }),
            Ret::Bool => match srng() % 6 {
                0 | 1 => 0,
                2 | 3 => 1,
                4 => 0x100,
                _ => srng(),
            },
            Ret::Ptr(n) => {
                if srng() % 4 == 0 {
                    0
                } else {
                    POOLS.with(|p| {
                        let p = p.borrow();
                        let pool = &p[n];
                        pool[srng() as usize % pool.len()]
                    })
                }
            }
        }
    }

    static mut ST0V: f64 = 0.0;
    pub static TRACE: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

    /// `stub_common` for the callees that return on ST0.
    #[unsafe(naked)]
    extern "C" fn stub_common_st0() {
        std::arch::naked_asm!(
            "pushad",
            "lea eax, [esp + 44]",
            "push eax",
            "push dword ptr [esp + 40]",
            "lea eax, [esp + 8]",
            "push eax",
            "call {f}",
            "add esp, 12",
            "mov [esp + 28], eax",
            "popad",
            "fld qword ptr [{v}]",
            "ret 4",
            f = sym stub_rs,
            v = sym ST0V,
        )
    }

    #[unsafe(naked)]
    extern "C" fn stub_common() {
        std::arch::naked_asm!(
            "pushad",
            "lea eax, [esp + 44]",
            "push eax",
            "push dword ptr [esp + 40]",
            "lea eax, [esp + 8]",
            "push eax",
            "call {f}",
            "add esp, 12",
            "mov [esp + 28], eax",
            "popad",
            "ret 4",
            f = sym stub_rs,
        )
    }

    /// Reports a crash with the faulting address and where it happened (original copy offset).
    unsafe extern "system" fn veh(info: *mut windows_sys::Win32::System::Diagnostics::Debug::EXCEPTION_POINTERS) -> i32 {
        unsafe {
            let rec = &*(*info).ExceptionRecord;
            let ctx = &*(*info).ContextRecord;
            let orig = ORIG_AT.with(|o| o.get());
            eprintln!(
                "EXCEPTION {:#x} at eip {:#x} (original +{:#x}) access {:x?} eax {:#x} ecx {:#x} edx {:#x} ebx {:#x} esi {:#x} edi {:#x} ebp {:#x}",
                rec.ExceptionCode, ctx.Eip, (ctx.Eip as usize).wrapping_sub(orig), &rec.ExceptionInformation[..2], ctx.Eax, ctx.Ecx, ctx.Edx, ctx.Ebx, ctx.Esi, ctx.Edi, ctx.Ebp
            );
            eprintln!("{}", std::backtrace::Backtrace::force_capture());
        }
        0
    }

    thread_local! {
        static ORIG_AT: Cell<usize> = const { Cell::new(0) };
    }

    /// The exe's bytes at a virtual address (read from the unpacked exe on disk).
    pub fn exe_bytes(va: usize, n: usize) -> Vec<u8> {
        static EXE: std::sync::OnceLock<Vec<u8>> = std::sync::OnceLock::new();
        let exe = EXE.get_or_init(|| std::fs::read(r"F:\Saints Row 2 Decomp\bin\SR2_pc.unpacked.exe").expect("exe"));
        let u32at = |o: usize| u32::from_le_bytes(exe[o..o + 4].try_into().unwrap()) as usize;
        let u16at = |o: usize| u16::from_le_bytes(exe[o..o + 2].try_into().unwrap()) as usize;
        let pe = u32at(0x3C);
        let nsec = u16at(pe + 6);
        let opt = u16at(pe + 20);
        for i in 0..nsec {
            let s = pe + 24 + opt + i * 40;
            let (vsz, va0, rsz, raw) = (u32at(s + 8), u32at(s + 12), u32at(s + 16), u32at(s + 20));
            if va >= va0 + 0x40_0000 && va < va0 + 0x40_0000 + vsz.max(rsz) {
                let o = raw + va - va0 - 0x40_0000;
                return exe[o..o + n].to_vec();
            }
        }
        panic!("{va:#x} is not in a section");
    }

    /// Copies `n` bytes of the exe at `va` into the shifted game memory (a constant the original reads).
    pub fn put_const(va: usize, n: usize) {
        let b = exe_bytes(va, n);
        unsafe { std::ptr::copy_nonoverlapping(b.as_ptr(), super::tr(va) as *mut u8, n) };
    }

    /// A private executable copy of an original body (its absolute data references moved by `DELTA`,
    /// its calls aimed at the callees' stubs / natives): used for a callee that runs for real.
    pub fn exec_copy(base: usize, body: &[u8], calls: &[usize], disps: &[usize]) -> usize {
        let orig = exec_alloc(body.len() + 16);
        unsafe { std::ptr::copy_nonoverlapping(body.as_ptr(), orig as *mut u8, body.len()) };
        for &off in disps {
            let v = u32::from_le_bytes(body[off..off + 4].try_into().unwrap()).wrapping_add(super::DELTA as u32);
            unsafe { std::ptr::write_unaligned((orig + off) as *mut u32, v) };
        }
        for &off in calls {
            let rel = i32::from_le_bytes(body[off + 1..off + 5].try_into().unwrap());
            let target = (base + off + 5).wrapping_add(rel as usize);
            let dest = redirect(target);
            let r = (dest as i32).wrapping_sub((orig + off + 5) as i32);
            unsafe { std::ptr::write_unaligned((orig + off + 1) as *mut i32, r) };
        }
        orig
    }

    pub struct Harness {
        pub mem: Mem,
        /// The original body, relocated to a private copy with its calls aimed at the stubs.
        pub orig: usize,
        pub thunk: usize,
    }

    /// What a case compares besides the call log and the memory.
    #[derive(Clone, Copy)]
    pub struct Cmp {
        /// Bits of EAX that must agree.
        pub eax_mask: u32,
        /// The original returns an f32 on ST0 (compared as f32; NaNs equal).
        pub st0: bool,
        /// Bytes the original pops itself (`ret N`).
        pub pop: usize,
        /// Registers (bit i of eax, ecx, edx, ebx, esi, edi, ebp) that must come back as they went in.
        pub preserved: u8,
        /// Registers (same bit order) whose value after the call must be the same in both runs.
        pub same: u8,
    }

    /// Executable memory for the stubs and the patched copy.
    fn exec_alloc(len: usize) -> usize {
        let p = unsafe { VirtualAlloc(std::ptr::null(), len, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE) } as usize;
        assert!(p != 0);
        p
    }

    impl Harness {
        /// `base`: the original's address; `body` / `calls`: its bytes and the offsets of its `call
        /// rel32`s; `thunk`: the Rust replacement's entry.
        pub fn new(base: usize, body: &[u8], calls: &[usize], disps: &[usize], callees: Vec<Callee>, extra: &[(usize, usize)], thunk: usize) -> Harness {
            let mem = Mem::new(body, extra);
            fixed(STACK, STACK_LEN);
            let stubs = exec_alloc(callees.len() * 16 + 16);
            let mut addrs = Vec::new();
            for (i, c) in callees.iter().enumerate() {
                let a = stubs + i * 16;
                let mut code = [0x90u8; 16];
                code[0] = 0x68;
                code[1..5].copy_from_slice(&(i as u32).to_le_bytes());
                code[5] = 0xE8;
                let common = if c.ret == Ret::St0 { stub_common_st0 as *const () as usize } else { stub_common as *const () as usize };
                let rel = (common as i32).wrapping_sub((a + 10) as i32);
                code[6..10].copy_from_slice(&rel.to_le_bytes());
                if c.pop == 0 {
                    code[10] = 0xC3;
                } else {
                    code[10] = 0xC2;
                    code[11..13].copy_from_slice(&(c.pop as u16).to_le_bytes());
                }
                unsafe { std::ptr::copy_nonoverlapping(code.as_ptr(), a as *mut u8, 16) };
                addrs.push(a);
            }
            CALLEES.with(|c| *c.borrow_mut() = callees.clone());
            STUBS.with(|s| *s.borrow_mut() = addrs.clone());
            let orig = exec_copy(base, body, calls, disps);
            ORIG_AT.with(|o| o.set(orig));
            static ONCE: std::sync::Once = std::sync::Once::new();
            ONCE.call_once(|| unsafe {
                windows_sys::Win32::System::Diagnostics::Debug::AddVectoredExceptionHandler(1, Some(veh));
            });
            Harness { mem, orig, thunk }
        }

        fn run(&self, f: usize, inp: super::Regs, args: [u32; 12], seed: u64, c: &Cmp) -> (Vec<Vec<u32>>, super::Regs, f64, u32) {
            SRNG.with(|s| s.set(seed | 1));
            unsafe { std::ptr::write_bytes((STACK + STACK_LEN - 0x1_0000) as *mut u8, 0, 0x1_0000) };
            // a clean x87 (53-bit precision, as the game runs)
            unsafe { std::arch::asm!("fninit", "fldcw word ptr [{cw}]", cw = in(reg) &0x027Fu16 as *const u16, options(nostack)) };
            LOG.with(|l| l.borrow_mut().clear());
            let (r, st0, sw) = unsafe { super::call_orig(f, &inp, &args, c.pop, c.st0, (STACK + STACK_LEN - 0x100) as u32) };
            (LOG.with(|l| std::mem::take(&mut *l.borrow_mut())), r, st0, sw)
        }

        /// One case on the current memory: original, then Rust, from the same snapshot.
        pub fn check(&self, inp: super::Regs, args: [u32; 12], seed: u64, c: Cmp) -> Result<(), String> {
            let snap = self.mem.snapshot();
            let (la, ra, sa, wa) = self.run(self.orig, inp, args, seed, &c);
            let after_a = self.mem.snapshot();
            self.mem.restore(&snap);
            let (lb, rb, sb, wb) = self.run(self.thunk, inp, args, seed, &c);
            let after_b = self.mem.snapshot();
            if (ra.eax ^ rb.eax) & c.eax_mask != 0 {
                return Err(format!("eax: original {:#x} rust {:#x}", ra.eax, rb.eax));
            }
            if c.st0 {
                let (x, y) = ((sa as f32).to_bits(), (sb as f32).to_bits());
                let nan = |b: u32| b & 0x7F80_0000 == 0x7F80_0000 && b & 0x7F_FFFF != 0;
                if x != y && !(nan(x) && nan(y)) {
                    return Err(format!("st0: original {x:#x} ({sa}) rust {y:#x} ({sb})"));
                }
            }
            if (wa & 0x3800) != (wb & 0x3800) {
                return Err(format!("x87 depth: original sw {wa:#x} rust sw {wb:#x}"));
            }
            for i in 0..7 {
                if c.preserved & (1 << i) != 0 {
                    let (x, y, z) = (inp.get(i), ra.get(i), rb.get(i));
                    if x != y || x != z {
                        return Err(format!("register {}: in {x:#x} original {y:#x} rust {z:#x}", super::REG_NAMES[i]));
                    }
                }
            }
            for i in 0..7 {
                if c.same & (1 << i) != 0 && ra.get(i) != rb.get(i) {
                    return Err(format!("register {} after the call: original {:#x} rust {:#x}", super::REG_NAMES[i], ra.get(i), rb.get(i)));
                }
            }
            for (i, (a, b)) in la.iter().zip(&lb).enumerate() {
                if a != b {
                    let prev: Vec<&Vec<u32>> = la[i.saturating_sub(3)..i].iter().collect();
                    return Err(format!("call #{i} differs:\n  previous {:x?}\n  original {:x?}\n  rust     {:x?}", prev, a, b));
                }
            }
            if la.len() != lb.len() {
                let longer = if la.len() > lb.len() { ("original", &la) } else { ("rust", &lb) };
                return Err(format!("original made {} calls, rust {}; the {} next calls {:x?}", la.len(), lb.len(), longer.0, longer.1[la.len().min(lb.len())]));
            }
            if let Some((a, x, y)) = self.mem.first_diff(&after_a, &after_b) {
                return Err(format!("memory differs at {a:#x}: original {x:#x} rust {y:#x} ({} bytes differ)", self.mem.count_diffs(&after_a, &after_b)));
            }
            Ok(())
        }
    }

    pub fn lock() -> std::sync::MutexGuard<'static, ()> {
        static L: std::sync::Mutex<()> = std::sync::Mutex::new(());
        L.lock().unwrap_or_else(|e| e.into_inner())
    }
    /// Where the test world's objects live.
    pub const ARENA: usize = 0x6000_0000;
    /// The tests run on a stack of their own, outside the game's address range.
    pub const STACK: usize = 0x6100_0000;
    pub const STACK_LEN: usize = 0x10_0000;
    pub const ARENA_LEN: usize = 0x18_0000;

    /// A bump allocator over the arena for one case.
    pub struct Arena(pub usize);
    impl Arena {
        pub fn new() -> Arena {
            Arena(ARENA)
        }
        /// `n` objects of `size` bytes (random contents are the caller's business).
        pub fn pool(&mut self, n: usize, size: usize) -> Vec<u32> {
            let v = (0..n).map(|i| (self.0 + i * size) as u32).collect();
            self.0 += n * size;
            assert!(self.0 <= ARENA + ARENA_LEN, "arena full");
            v
        }
    }

    pub unsafe fn put(a: u32, off: usize, v: u32) {
        unsafe { *((a as usize + off) as *mut u32) = v }
    }
    pub unsafe fn putb(a: u32, off: usize, v: u8) {
        unsafe { *((a as usize + off) as *mut u8) = v }
    }
}

// =================================================================================================
// Offline differential tests (shared pieces)
// =================================================================================================
//
// Each test runs the ORIGINAL bytes (copied to executable memory, their calls aimed at recording stubs
// or native stand-ins, their absolute data references moved by DELTA) and the Rust port through its real
// thunk on the same random world, from the same snapshot, and compares: the callee call log (registers
// the callee reads, stack arguments), the result registers / ST0, every register the original preserves,
// the x87 depth, and every byte of the mapped globals and of the arena.
//
// Run each test in its own process:
//   RUSTFLAGS="-C target-feature=+crt-static -C link-arg=/DYNAMICBASE:NO -C link-arg=/BASE:0x10000000" \
//   cargo test --release -p sr2-hook --target i686-pc-windows-msvc <name> -- --ignored --test-threads=1
// (CASES=n changes the number of random cases, default 4000.)

#[cfg(test)]
mod tc {
    pub use super::dt::*;
    pub use super::*;

    pub const ESI0: u32 = 0x5151_5151;
    pub const EDI0: u32 = 0xD1D1_D1D1;

    pub fn regs(eax: u32, ecx: u32, edx: u32, esi: u32, edi: u32) -> Regs {
        Regs { eax, ecx, edx, ebx: 0xB1B1_B1B1, esi, edi, ebp: 0xE9E9_E9E9 }
    }

    pub fn cases() -> u32 {
        std::env::var("CASES").ok().and_then(|v| v.parse().ok()).unwrap_or(4000)
    }

    /// A coordinate: mostly sane, now and then awkward.
    pub fn coord(rng: &mut Rng) -> u32 {
        match rng.below(40) {
            0 => rng.float_bits(),
            1 => 0,
            2 => (rng.below(6) as f32).to_bits(),
            _ => (rng.below(40000) as f32 / 20.0 - 1000.0).to_bits(),
        }
    }

    pub unsafe fn put_vec3(p: u32, rng: &mut Rng) {
        for k in 0..3 {
            put(p, k * 4, coord(rng));
        }
    }

    /// Runs `n` cases: `world` builds one (and returns the registers, arguments, seed and comparison).
    pub fn run_cases(h: &Harness, n: u32, mut world: impl FnMut(&Harness, &mut Rng) -> (Regs, [u32; 12], Cmp), name: &str) {
        let mut rng = Rng(0x1234_5678_9ABC_DEF1);
        let mut bad = 0;
        for i in 0..n {
            let (r, a, c) = world(h, &mut rng);
            if let Err(e) = h.check(r, a, rng.u32() as u64, c) {
                bad += 1;
                if bad <= 5 {
                    eprintln!("{name} case {i}: regs {r:x?} args {:x?}: {e}", &a[..6]);
                }
            }
        }
        eprintln!("{name}: {n} cases, {bad} differ");
        assert_eq!(bad, 0, "{bad} of {n} cases differ");
    }

    pub fn args(v: &[u32]) -> [u32; 12] {
        let mut a = [0u32; 12];
        a[..v.len()].copy_from_slice(v);
        a
    }
}

#[cfg(test)]
mod tests_a {
    use super::tc::*;

    // --- 0xA8A4F0 road_query_random_lane_setup ---------------------------------------------------------

    #[test]
    #[ignore = "needs the test exe linked at /BASE:0x10000000 (see the kit comment)"]
    fn rq_setup_matches_original() {
        let _g = lock();
        let callees = vec![callee(0xBF77B0, 6, 0x18, EAX | ECX | EDX | ESI | EDI, Ret::Any, Fx::None)];
        let h = Harness::new(0xA8A4F0, &RQ_SETUP_BODY, &RQ_SETUP_BODY_CALLS, &RQ_SETUP_BODY_DISPS, callees, &[], rq_setup_thunk as *const () as usize);
        run_cases(
            &h,
            cases(),
            |h, rng| unsafe {
                h.mem.fill_random(rng);
                let mut a = Arena::new();
                let net = a.pool(1, 0x100)[0];
                let tree = a.pool(1, 0x40)[0];
                let centre = a.pool(1, 0x10)[0];
                let out = a.pool(1, 0x10)[0];
                put_vec3(centre, rng);
                wd(0x0222_5B64, if rng.one_in(8) { 0 } else { net });
                put(net, 0x84, if rng.one_in(8) { 0 } else { tree });
                put(tree, 0, rng.u32());
                put(tree, 8, rng.u32());
                put(out, 0, rng.u32());
                let f = |rng: &mut Rng| if rng.one_in(3) { rng.float_bits() } else { coord(rng) };
                let ar = args(&[f(rng), rng.u32(), rng.u32(), rng.u32(), f(rng), f(rng)]);
                (
                    regs(centre, rng.u32(), out, ESI0, EDI0),
                    ar,
                    Cmp { eax_mask: 0, st0: false, pop: 0, preserved: SAVED, same: 0 },
                )
            },
            "rq_setup",
        );
    }

    // --- 0xA103B0 nav_tri_edge_midpoint ----------------------------------------------------------------

    #[test]
    #[ignore = "needs the test exe linked at /BASE:0x10000000 (see the kit comment)"]
    fn mid_matches_original() {
        let _g = lock();
        let h = Harness::new(0xA103B0, &MID_BODY, &MID_BODY_CALLS, &MID_BODY_DISPS, vec![], &[(0xE5BF70, 8)], mid_thunk as *const () as usize);
        run_cases(
            &h,
            cases(),
            |h, rng| unsafe {
                h.mem.fill_random(rng);
                put_const(0xE5BF70, 8);
                let mut a = Arena::new();
                let verts = a.pool(6, 0x10);
                let blk = a.pool(1, 0x100)[0];
                let cell = blk + 0x80;
                for k in 0..24 {
                    put(cell, k * 4 - 0x20, verts[rng.below(6) as usize]);
                }
                for &v in &verts {
                    put_vec3(v, rng);
                }
                let out = a.pool(1, 0x10)[0];
                for k in 0..3 {
                    put(out, k * 4, rng.u32());
                }
                let i = rng.below(10) as i32 - 3;
                (
                    regs(rng.u32(), out, rng.u32(), i as u32, cell),
                    args(&[]),
                    Cmp { eax_mask: u32::MAX, st0: false, pop: 0, preserved: 2 | SAVED, same: 4 },
                )
            },
            "mid",
        );
    }

    // --- 0xA11750 nav_cells_heuristic ------------------------------------------------------------------

    extern "C" fn sqrtf_native(x: f32) -> f32 {
        // NaN payloads depend on which NaN operand x87 vs SSE picks; only the class is compared
        push_log(vec![SQRTF_ADDR as u32, if x.is_nan() { 0x7FC0_0000 } else { x.to_bits() }]);
        (x as f64).sqrt() as f32
    }

    #[test]
    #[ignore = "needs the test exe linked at /BASE:0x10000000 (see the kit comment)"]
    fn heur_matches_original() {
        let _g = lock();
        let mid = exec_copy(0xA103B0, &MID_BODY, &MID_BODY_CALLS, &MID_BODY_DISPS);
        let mut c_mid = callee(0xA103B0, 0, 0, ECX | EDI | ESI, Ret::Any, Fx::None);
        c_mid.native = mid;
        let mut c_sqrt = callee(SQRTF_ADDR, 1, 0, 0, Ret::St0, Fx::None);
        c_sqrt.native = sqrtf_native as *const () as usize;
        let h = Harness::new(
            0xA11750,
            &HEUR_BODY,
            &HEUR_BODY_CALLS,
            &HEUR_BODY_DISPS,
            vec![c_mid, c_sqrt],
            &[(0xE5BF70, 8), (0xE5C408, 8), (0xE5C190, 8), (0xE5C638, 8), (0xE8E0D8, 4), (0xDD0C4C, 4)],
            heur_thunk as *const () as usize,
        );
        run_cases(
            &h,
            cases(),
            |h, rng| unsafe {
                h.mem.fill_random(rng);
                for (va, n) in [(0xE5BF70, 8), (0xE5C408, 8), (0xE5C190, 8), (0xE5C638, 8), (0xE8E0D8, 4), (0xDD0C4C, 4)] {
                    put_const(va, n);
                }
                let mut a = Arena::new();
                let verts = a.pool(8, 0x10);
                for &v in &verts {
                    put_vec3(v, rng);
                }
                let cells = a.pool(2, 0x30);
                let nb = a.pool(2, 0x30);
                for &c in &cells {
                    for k in 0..3 {
                        put(c, k * 4, verts[rng.below(8) as usize]);
                        put(c, 0xC + k * 4, if rng.one_in(3) { 0 } else { nb[rng.below(2) as usize] });
                    }
                }
                let pos = a.pool(2, 0x10);
                for &p in &pos {
                    put_vec3(p, rng);
                }
                let wide = match rng.below(4) {
                    0 => 0,
                    1 => 1,
                    2 => 0xFFFF_FF00 | (rng.below(2)),
                    _ => rng.u32(),
                };
                (
                    regs(rng.u32(), rng.u32(), rng.u32(), ESI0, EDI0),
                    args(&[cells[0], pos[0], cells[1], pos[1], wide]),
                    Cmp { eax_mask: 0, st0: true, pop: 0, preserved: SAVED, same: 0 },
                )
            },
            "heur",
        );
    }
}

#[cfg(test)]
mod tests_b {
    use super::tc::*;

    // natives standing in for the three pure math callees of nav_poly_link_match; they log their inputs
    // (what the callees read) and do deterministic f32 math, so both runs see the same numbers.

    extern "C" fn norm3_rs(v: *mut f32) {
        unsafe {
            let a = [*v, *v.add(1), *v.add(2)];
            push_log(vec![VEC3_NORMALIZE_ADDR as u32, a[0].to_bits(), a[1].to_bits(), a[2].to_bits()]);
            let s = a[0] * a[0] + a[1] * a[1] + a[2] * a[2];
            let inv = 1.0 / s.sqrt();
            *v = a[0] * inv;
            *v.add(1) = a[1] * inv;
            *v.add(2) = a[2] * inv;
        }
    }
    #[unsafe(naked)]
    extern "C" fn norm3_native() {
        std::arch::naked_asm!("push esi", "call {f}", "add esp, 4", "ret", f = sym norm3_rs)
    }

    extern "C" fn norm_len_rs(v: *mut f32) -> f32 {
        unsafe {
            let a = [*v, *v.add(1), *v.add(2)];
            push_log(vec![VEC3_NORMALIZE_LEN_ADDR as u32, a[0].to_bits(), a[1].to_bits(), a[2].to_bits()]);
            let s = a[0] * a[0] + a[1] * a[1] + a[2] * a[2];
            let len = s.sqrt();
            let inv = 1.0 / len;
            *v = a[0] * inv;
            *v.add(1) = a[1] * inv;
            *v.add(2) = a[2] * inv;
            len
        }
    }
    #[unsafe(naked)]
    extern "C" fn norm_len_native() {
        std::arch::naked_asm!(
            "push esi",
            "call {f}",
            "add esp, 4",
            "sub esp, 4",
            "fstp dword ptr [esp]",
            "movss xmm0, dword ptr [esp]",
            "add esp, 4",
            "ret",
            f = sym norm_len_rs,
        )
    }

    extern "C" fn seg_rs(out: *mut f32, a: *const f32, b: *const f32, p: *const f32) {
        unsafe {
            push_log(vec![SEG_CLOSEST_XZ_ADDR as u32, (*a).to_bits(), (*a.add(1)).to_bits(), (*b).to_bits(), (*b.add(1)).to_bits(), (*p).to_bits(), (*p.add(1)).to_bits()]);
            let (ax, az, bx, bz, px, pz) = (*a, *a.add(1), *b, *b.add(1), *p, *p.add(1));
            let (dx, dz) = (bx - ax, bz - az);
            let t = ((px - ax) * dx + (pz - az) * dz) / (dx * dx + dz * dz);
            let t = if t > 0.0 { if t < 1.0 { t } else { 1.0 } } else { 0.0 };
            *out = ax + t * dx;
            *out.add(1) = az + t * dz;
        }
    }
    #[unsafe(naked)]
    extern "C" fn seg_native() {
        std::arch::naked_asm!("push edi", "push edx", "push ecx", "push esi", "call {f}", "add esp, 16", "ret", f = sym seg_rs)
    }

    #[test]
    #[ignore = "needs the test exe linked at /BASE:0x10000000 (see the kit comment)"]
    fn link_matches_original() {
        let _g = lock();
        let mut c1 = callee(VEC3_NORMALIZE_ADDR, 0, 0, ESI, Ret::Any, Fx::None);
        c1.native = norm3_native as *const () as usize;
        let mut c2 = callee(VEC3_NORMALIZE_LEN_ADDR, 0, 0, ESI, Ret::Any, Fx::None);
        c2.native = norm_len_native as *const () as usize;
        let mut c3 = callee(SEG_CLOSEST_XZ_ADDR, 0, 0, ECX | EDX | EDI | ESI, Ret::Any, Fx::None);
        c3.native = seg_native as *const () as usize;
        let consts: [(usize, usize); 6] = [(0xE87998, 4), (0xE5BF70, 8), (0xE5BFC8, 8), (0xE44850, 4), (0xE5CDA0, 8), (0x252A6D0, 12)];
        let h = Harness::new(0xA16650, &LINK_BODY, &LINK_BODY_CALLS, &LINK_BODY_DISPS, vec![c1, c2, c3], &consts, link_thunk as *const () as usize);
        let wrote = std::cell::Cell::new([0u32; 4]);
        let first = std::cell::Cell::new(true);
        run_cases(
            &h,
            cases(),
            |h, rng| unsafe {
                let outp = ARENA + 0x2000;
                if !first.replace(false) {
                    // the previous case's outputs (the slot lives at a fixed arena address)
                    let o0 = *(outp as *const u32);
                    let o1 = *((outp + 4) as *const u32);
                    let mut w = wrote.get();
                    w[0] += 1;
                    w[1] += (o0 != 0xDEAD_BEEF) as u32;
                    w[2] += (o1 != 0xDEAD_BEEF) as u32;
                    wrote.set(w);
                }
                h.mem.fill_random(rng);
                for (va, n) in consts {
                    if va < 0x100_0000 {
                        put_const(va, n);
                    }
                }
                for k in 0..3 {
                    wd(0x252A6D0 + 4 * k, 0);
                }
                let mut a = Arena::new();
                let nv = if rng.one_in(60) { 0 } else { 1 + rng.below(12) as usize };
                let verts = a.pool(16, 0x10);
                let grid = |rng: &mut Rng| ((rng.below(160) as f32 - 80.0) * 0.25).to_bits();
                for &v in &verts {
                    put(v, 0, grid(rng));
                    put(v, 4, grid(rng));
                    put(v, 8, grid(rng));
                    if rng.one_in(80) {
                        put(v, rng.below(3) as usize * 4, rng.float_bits());
                    }
                }
                let vptrs = a.pool(1, 0x80)[0];
                for k in 0..16 {
                    put(vptrs, k * 4, verts[k]);
                }
                // the arena bump allocator is per case; the out slot lives at a fixed address
                let item = a.pool(1, 0x10)[0];
                // keep `outp` clear of the pools: they start at ARENA and are small
                put(item, 0, vptrs);
                put(item, 4, outp as u32);
                put(item, 8, nv as u32 | (rng.u32() & 0xFFFF_0000));
                put(outp as u32, 0, 0xDEAD_BEEF);
                put(outp as u32, 4, 0xDEAD_BEEF);
                let rec = a.pool(1, 0x200)[0];
                put(rec, 8, rng.u32());
                // bounds around the polygon (sometimes missing it)
                let bx = |rng: &mut Rng| ((rng.below(240) as f32 - 120.0) * 0.25).to_bits();
                for off in [0x28usize, 0x30, 0x34, 0x3C] {
                    put(rec, off, bx(rng));
                }
                if rng.below(3) != 0 {
                    let (lx, hx) = (f32::from_bits(rd(verts[0] as usize)) - 30.0, f32::from_bits(rd(verts[0] as usize)) + 30.0);
                    let (lz, hz) = (f32::from_bits(rd(verts[0] as usize + 8)) - 30.0, f32::from_bits(rd(verts[0] as usize + 8)) + 30.0);
                    put(rec, 0x28, lx.to_bits());
                    put(rec, 0x34, hx.to_bits());
                    put(rec, 0x30, lz.to_bits());
                    put(rec, 0x3C, hz.to_bits());
                }
                let nl = if rng.one_in(20) { rng.below(3) as u32 } else { 1 + rng.below(9) };
                let nl = if rng.one_in(60) { (-(rng.below(3) as i32)) as u32 } else { nl };
                let links = a.pool(10, 0x20);
                put(rec, 0x14C, nl);
                put(rec, 0x150, links[0]);
                let nlu = (nl as i32).clamp(0, 10) as usize;
                for k in 0..nlu {
                    let l = links[k];
                    let f = |v: f32| v.to_bits();
                    let key = *[0xFFFF_FFFFu32, 0xFFFF_FFFF, 0xFFFF_FFFF, 0, 1, 2, 0x8000_0000].get(rng.below(7) as usize).unwrap();
                    put(l, 0x1C, key);
                    if k > 0 && rng.one_in(3) {
                        // a (noisy) reversed or same-direction twin of the previous link
                        let pl = links[k - 1];
                        let rev = rng.one_in(2);
                        let noise = |rng: &mut Rng| (rng.below(9) as f32 - 4.0) * 0.05;
                        let sidx = if rev { [0xCusize, 0x10, 0x14, 0, 4, 8] } else { [0, 4, 8, 0xC, 0x10, 0x14] };
                        for q in 0..6 {
                            let base = f32::from_bits(rd(pl as usize + sidx[q]));
                            put(l, [0usize, 4, 8, 0xC, 0x10, 0x14][q], f(base + if rng.one_in(3) { 0.0 } else { noise(rng) }));
                        }
                        if rng.one_in(2) {
                            put(l, 0x1C, rd(pl as usize + 0x1C));
                        }
                    } else {
                        for q in [0usize, 4, 8, 0xC, 0x10, 0x14] {
                            let v = if rng.one_in(2) {
                                f(f32::from_bits(rd(verts[rng.below(12) as usize] as usize + (q % 12))) + (rng.below(5) as f32 - 2.0) * 0.1)
                            } else {
                                grid(rng)
                            };
                            put(l, q, v);
                        }
                        if rng.one_in(8) {
                            // a degenerate link (start == end in x, z)
                            put(l, 0xC, rd(l as usize));
                            put(l, 0x14, rd(l as usize + 8));
                        }
                    }
                }
                (
                    regs(rng.u32(), rng.u32(), rng.u32(), ESI0, EDI0),
                    args(&[item, rec]),
                    Cmp { eax_mask: 0, st0: false, pop: 0, preserved: SAVED, same: 0 },
                )
            },
            "link",
        );
        eprintln!("link: out0 written in {} of {} cases, out1 written in {}", wrote.get()[1], wrote.get()[0], wrote.get()[2]);
    }
}

#[cfg(test)]
mod tests_c {
    use super::tc::*;

    const CONSTS: [(usize, usize); 0] = [];

    /// Cells in the arena with valid scratch records; returns the cells.
    unsafe fn heap_world(h: &Harness, rng: &mut Rng, a: &mut Arena, n: usize) -> Vec<u32> {
        unsafe {
            h.mem.fill_random(rng);
            let gen0 = rng.mix(&[1, 2, 7, 0xFFFF_FFFF], 0).max(1);
            wd(GEN, gen0);
            let cells = a.pool(n.max(1), 0x30);
            for (i, &c) in cells.iter().enumerate() {
                put(c, 0x20, gen0);
                let idx = (i as u32) * 2 + rng.below(2);
                put(c, 0x1C, 0);
                *((c as usize + 0x1E) as *mut u16) = idx as u16;
                let rec = tr(SCR + idx as usize * 24);
                let key = |rng: &mut Rng| match rng.below(6) {
                    0 => 0f32,
                    1 => rng.below(4) as f32,
                    2 => f32::from_bits(rng.float_bits()),
                    _ => rng.below(50) as f32 * 0.5,
                };
                *(rec as *mut f32) = key(rng);
                *((rec + 4) as *mut f32) = key(rng);
                *((rec + 0x15) as *mut u8) = rng.below(2) as u8;
                *((rec + 0x16) as *mut u16) = rng.u32() as u16;
            }
            cells
        }
    }

    #[test]
    #[ignore = "needs the test exe linked at /BASE:0x10000000 (see the kit comment)"]
    fn pop_matches_original() {
        let _g = lock();
        let c = vec![callee(SIFT_DOWN, 1, 4, 0, Ret::Any, Fx::None)];
        let h = Harness::new(0xA10080, &POP_BODY, &POP_BODY_CALLS, &POP_BODY_DISPS, c, &[], pop_thunk as *const () as usize);
        run_cases(
            &h,
            cases(),
            |h, rng| unsafe {
                let mut a = Arena::new();
                let n = rng.below(14) as usize;
                let cells = heap_world(h, rng, &mut a, n);
                wd(HEAP_CNT, if rng.one_in(10) { rng.pick(&[0u32, 0xFFFF_FFFF]) } else { n as u32 });
                for i in 0..n {
                    wd(HEAP + 4 * i, cells[rng.below(n as u32) as usize]);
                }
                (
                    regs(rng.u32(), rng.u32(), rng.u32(), ESI0, EDI0),
                    args(&[]),
                    Cmp { eax_mask: u32::MAX, st0: false, pop: 0, preserved: SAVED, same: 0 },
                )
            },
            "pop",
        );
    }

    #[test]
    #[ignore = "needs the test exe linked at /BASE:0x10000000 (see the kit comment)"]
    fn sift_up_matches_original() {
        let _g = lock();
        let c = vec![callee(SIFT_DOWN, 1, 4, 0, Ret::Any, Fx::None)];
        let h = Harness::new(0xA10260, &SIFT_UP_BODY, &SIFT_UP_BODY_CALLS, &SIFT_UP_BODY_DISPS, c, &[], sift_up_thunk as *const () as usize);
        run_cases(
            &h,
            cases(),
            |h, rng| unsafe {
                let mut a = Arena::new();
                let n = 1 + rng.below(14) as usize;
                let cells = heap_world(h, rng, &mut a, n);
                wd(HEAP_CNT, n as u32);
                for i in 0..n {
                    wd(HEAP + 4 * i, cells[i]);
                }
                let idx = rng.below(n as u32 + 3);
                                (
                    regs(rng.u32(), rng.u32(), rng.u32(), ESI0, EDI0),
                    args(&[idx]),
                    Cmp { eax_mask: 0, st0: false, pop: 4, preserved: SAVED, same: 2 },
                )
            },
            "sift_up",
        );
    }

    #[test]
    #[ignore = "needs the test exe linked at /BASE:0x10000000 (see the kit comment)"]
    fn vclear_matches_original() {
        let _g = lock();
        let h = Harness::new(0xA12AE0, &VCLEAR_BODY, &VCLEAR_BODY_CALLS, &VCLEAR_BODY_DISPS, vec![], &[], vclear_thunk as *const () as usize);
        run_cases(
            &h,
            cases(),
            |h, rng| unsafe {
                h.mem.fill_random(rng);
                let mut a = Arena::new();
                let cells = a.pool(6, 0x30);
                for &c in &cells {
                    put(c, 0x1C, rng.u32());
                }
                let n = rng.below(0x21);
                let n = if rng.one_in(12) { rng.pick(&[0u32, 0xFFFF_FFFF, 0x8000_0000]) } else { n };
                wd(VIS_CNT, n);
                for i in 0..0x20 {
                    wd(VIS + 4 * i, cells[rng.below(6) as usize]);
                }
                (
                    regs(rng.u32(), rng.u32(), rng.u32(), ESI0, EDI0),
                    args(&[]),
                    Cmp { eax_mask: 0, st0: false, pop: 0, preserved: SAVED, same: 0 },
                )
            },
            "vclear",
        );
    }

    #[test]
    #[ignore = "needs the test exe linked at /BASE:0x10000000 (see the kit comment)"]
    fn reach_matches_original() {
        let _g = lock();
        let callees = vec![
            callee(TRI_CENTROID, 0, 0, EDX | ESI, Ret::Any, Fx::Out3Esi),
            callee(CELLS_HEURISTIC, 5, 0, 0, Ret::St0, Fx::None),
            callee(RELAX, 3, 0, EAX | ECX, Ret::Bool, Fx::HeapCnt),
            callee(POP_ADDR, 0, 0, 0, Ret::PtrNz(0), Fx::None),
            callee(HAS_LINK2, 0, 0, EAX, Ret::Bool, Fx::None),
            callee(VEC3_DIST2, 0, 0, EAX | ECX, Ret::St0, Fx::None),
            callee(SQRTF_ADDR, 1, 0, 0, Ret::St0, Fx::None),
        ];
        let h = Harness::new(0xA14230, &REACH_BODY, &REACH_BODY_CALLS, &REACH_BODY_DISPS, callees, &[], reach_thunk as *const () as usize);
        run_cases(
            &h,
            cases(),
            |h, rng| unsafe {
                h.mem.fill_random(rng);
                let mut a = Arena::new();
                let gen0 = rng.mix(&[1, 2, 7, 0xFFFF_FFFF], 0);
                wd(GEN, gen0);
                let newgen = gen0.wrapping_add(1).max(1);
                let valid = a.pool(6, 0x30);
                let stale = a.pool(3, 0x30);
                let all: Vec<u32> = valid.iter().chain(stale.iter()).copied().collect();
                for (i, &c) in all.iter().enumerate() {
                    let ok = i < 6;
                    put(c, 0x20, if ok { newgen } else { newgen.wrapping_add(5) });
                    putb(c, 0x1D, rng.u32() as u8);
                    *((c as usize + 0x1E) as *mut u16) = (i as u16) * 2;
                    for k in 0..3 {
                        put(c, 0xC + 4 * k, if rng.one_in(4) { 0 } else { all[rng.below(9) as usize] });
                    }
                    let rec = tr(SCR + i * 2 * 24);
                    *(rec as *mut f32) = rng.below(40) as f32 * 0.5;
                    *((rec + 0x14) as *mut u8) = rng.pick(&[0xFFu8, 0, 1, 2, 0xFF, 5]);
                    *((rec + 0x15) as *mut u8) = rng.below(2) as u8;
                    for q in 0..3 {
                        *((rec + 8 + 4 * q) as *mut u32) = coord(rng);
                    }
                }
                set_pools(vec![valid.clone()]);
                wd(HEAP_CNT, rng.below(5));
                let flags = a.pool(1, 0x10)[0];
                putb(flags, 0, rng.u32() as u8);
                putb(flags, 1, rng.u32() as u8);
                let (ca, cb) = (valid[rng.below(6) as usize], valid[rng.below(6) as usize]);
                (
                    regs(rng.u32(), rng.u32(), rng.u32(), ESI0, EDI0),
                    args(&[ca, cb, flags]),
                    Cmp { eax_mask: 0xFF, st0: false, pop: 0, preserved: SAVED, same: 0 },
                )
            },
            "reach",
        );
    }
}

#[cfg(test)]
mod tests_d {
    use super::tc::*;

    const GOAL_FIELDS: &[(usize, usize)] = &[(0, 1), (4, 12), (0x10, 4), (0x18, 4), (0x24, 1), (0x28, 12)];

    /// The world shared by the three vehicle ports: a vehicle with a pool entry, the net globals and
    /// the two goal constants. Returns (vehicle, nodes array).
    unsafe fn veh_world(h: &Harness, rng: &mut Rng, a: &mut Arena, with_vehicle: bool) -> u32 {
        unsafe {
            h.mem.fill_random(rng);
            for va in [0xE38AE0usize, 0xE8725C] {
                put_const(va, 4);
            }
            wb(NET_EXTRA_BYTE, rng.below(2) as u8);
            wd(NET_SESSION, rng.u32());
            wd(0x2528C14, rng.u32());
            let veh = a.pool(1, 0x100)[0];
            let obj = a.pool(1, 0x100)[0];
            let blk = a.pool(1, 0x10)[0];
            let conn = a.pool(1, 0x10)[0];
            let _ = conn;
            let hnd = (1 + rng.below(0xFF)) << 12 | (1 + rng.below(4000));
            put(veh, 0x44, match rng.below(6) {
                0 => 0,
                1 => hnd ^ 0x1000,
                _ => hnd,
            });
            wd(OBJ_POOL + (((hnd & 0xFFF) as usize) << 4), if rng.one_in(5) { 0 } else { obj });
            put(obj, 0x44, if rng.one_in(6) { rng.u32() } else { hnd });
            put(obj, 0xB0, if rng.one_in(5) { 0 } else { blk });
            putb(blk, 0, rng.u32() as u8);
            *((blk as usize + 2) as *mut u16) = rng.pick(&[0xFFFFu16, 5, 0x1234, 0]);
            put(veh, 0xB0, if rng.one_in(4) { 0 } else { blk });
            if with_vehicle { veh } else { 0 }
        }
    }

    #[test]
    #[ignore = "needs the test exe linked at /BASE:0x10000000 (see the kit comment)"]
    fn navmesh_matches_original() {
        let _g = lock();
        let mut cookie = callee(0xC9604F, 0, 0, 0, Ret::Keep, Fx::None);
        cookie.silent = true;
        let callees = vec![
            callee(OWNED_LOCALLY, 0, 0, EAX, Ret::Bool, Fx::None),
            callee(FIND_CONN, 0, 0, EAX | EDX, Ret::Any, Fx::None),
            callee(NET_SEND, 4, 0, ESI, Ret::Any, Fx::LogBuf),
            callee(ORDER_05, 4, 0, 0, Ret::Any, Fx::LogArgMem(3, &[(0, 1), (4, 4), (8, 1), (0xC, 4)])),
            callee(GOAL_INSTALL, 3, 0, EAX | ECX, Ret::Any, Fx::LogEaxMem(GOAL_FIELDS)),
            cookie,
        ];
        let h = Harness::new(0xB28700, &NAVMESH_BODY, &NAVMESH_BODY_CALLS, &NAVMESH_BODY_DISPS, callees, &[(0xE38AE0, 4), (0xE8725C, 4), (OBJ_POOL, 0x1_0000)], navmesh_thunk as *const () as usize);
        run_cases(
            &h,
            cases(),
            |h, rng| unsafe {
                let mut a = Arena::new();
                let veh_real = veh_world(h, rng, &mut a, true);
                let veh = if rng.one_in(15) { 0 } else { veh_real };
                let nodes = a.pool(1, 0x80)[0];
                let nblk = a.pool(26, 0x30);
                for &n in &nblk {
                    for q in 0..3 {
                        put(n, 0x1C + 4 * q, coord(rng));
                    }
                }
                for k in 0..26 {
                    put(nodes, k * 4, nblk[rng.below(26) as usize]);
                }
                let count = match rng.below(12) {
                    0 => 0x1A,
                    1 => 0x7FFF_FFFF,
                    3 => 0x19,
                    _ => 1 + rng.below(24),
                };
                let b = |rng: &mut Rng| match rng.below(4) {
                    0 => 0,
                    1 => 1,
                    2 => rng.u32() & 0xFFFF_FF00,
                    _ => rng.u32(),
                };
                let ar = args(&[veh, count, b(rng), b(rng), b(rng), rng.u32()]);
                (
                    regs(rng.u32(), nodes, rng.u32(), ESI0, EDI0),
                    ar,
                    Cmp { eax_mask: u32::MAX, st0: false, pop: 0, preserved: SAVED, same: 0 },
                )
            },
            "navmesh",
        );
    }
}

#[cfg(test)]
mod tests_e {
    use super::tc::*;

    const GOAL_FIELDS: &[(usize, usize)] = &[(0, 1), (4, 12), (0x10, 4), (0x18, 4), (0x24, 1), (0x28, 12)];

    #[test]
    #[ignore = "needs the test exe linked at /BASE:0x10000000 (see the kit comment)"]
    fn nodes_matches_original() {
        let _g = lock();
        let mut cookie = callee(0xC9604F, 0, 0, 0, Ret::Keep, Fx::None);
        cookie.silent = true;
        let callees = vec![
            callee(OWNED_LOCALLY, 0, 0, EAX, Ret::Bool, Fx::None),
            callee(FIND_CONN, 0, 0, EAX | EDX, Ret::Any, Fx::None),
            callee(NET_SEND, 4, 0, ESI, Ret::Any, Fx::LogBuf),
            callee(NEAREST_LANE_MASK_ADDR, 0, 0, EAX, Ret::Any, Fx::None),
            callee(ROUTE_POS_OK, 0, 0, EAX | EDX, Ret::Bool, Fx::None),
            callee(LANE_CLASS, 0, 0, EAX, Ret::Bool, Fx::None),
            callee(FIND_LANE, 0, 0, EAX, Ret::PtrNz(1), Fx::LogEaxMem(&[(0, 4), (4, 4), (8, 4), (0xC, 4), (0x10, 4), (0x18, 2)])),
            callee(SPLINE_EVAL_POS, 1, 4, EAX | ESI, Ret::Any, Fx::Out3Esi),
            callee(ROUTE_BUILD_A, 1, 0, 0, Ret::Ptr(0), Fx::RouteBlock),
            callee(ROUTE_BUILD_B, 2, 0, 0, Ret::Ptr(0), Fx::RouteBlock),
            callee(SPLINE_CLOSEST, 0, 0, EAX | ESI | EDI, Ret::St0, Fx::Out3Esi),
            callee(ORDER_0E, 1, 0, ECX, Ret::Any, Fx::LogEcxMem(&[(0, 1), (4, 4), (8, 4), (0xC, 4), (0x10, 4)])),
            callee(ROUTE_TAIL_FN, 3, 0, EDI, Ret::Any, Fx::None),
            callee(GOAL_INIT, 0, 0, EAX, Ret::Any, Fx::ZeroEax(0x34)),
            callee(GOAL_INSTALL, 3, 0, EAX | ECX, Ret::Any, Fx::LogEaxMem(GOAL_FIELDS)),
            cookie,
        ];
        let h = Harness::new(
            0xB27D90,
            &NODES_BODY,
            &NODES_BODY_CALLS,
            &NODES_BODY_DISPS,
            callees,
            &[(0xE38AE0, 4), (0xE8725C, 4), (OBJ_POOL, 0x1_0000), (LANE_QUERY_F, 4), (HALF_F, 4)],
            nodes_thunk as *const () as usize,
        );
        run_cases(
            &h,
            cases(),
            |h, rng| unsafe {
                h.mem.fill_random(rng);
                for (va, n) in [(0xE38AE0usize, 4usize), (0xE8725C, 4), (LANE_QUERY_F, 4), (HALF_F, 4)] {
                    put_const(va, n);
                }
                let mut a = Arena::new();
                let veh = a.pool(1, 0x9000)[0];
                let obj = a.pool(1, 0x100)[0];
                let blk = a.pool(1, 0x10)[0];
                let hnd = (1 + rng.below(0xFF)) << 12 | (1 + rng.below(4000));
                put(veh, 0x44, if rng.one_in(6) { 0 } else { hnd });
                wd(OBJ_POOL + (((hnd & 0xFFF) as usize) << 4), if rng.one_in(5) { 0 } else { obj });
                put(obj, 0x44, if rng.one_in(6) { rng.u32() } else { hnd });
                put(obj, 0xB0, if rng.one_in(5) { 0 } else { blk });
                putb(blk, 0, rng.u32() as u8);
                *((blk as usize + 2) as *mut u16) = rng.pick(&[0xFFFFu16, 5, 0x1234, 0]);
                put(veh, 0xB0, if rng.one_in(4) { 0 } else { blk });
                putb(veh, 0x8566, rng.u32() as u8);
                for q in 0..3 {
                    put(veh, 0x14 + 4 * q, coord(rng));
                }
                wb(NET_EXTRA_BYTE, rng.below(2) as u8);
                wd(NET_SESSION, rng.u32());
                wd(0x2528C14, rng.u32());
                let lanes = a.pool(2, 0x40);
                let routes = a.pool(3, 0x40);
                let rblk = a.pool(3, 0x40);
                for (i, &r) in routes.iter().enumerate() {
                    put(r, 4, rblk[i]);
                    put(rblk[i], 0xC, rng.u32());
                    put(r, 0xC, rng.u32());
                }
                set_pools(vec![routes.clone(), lanes.clone()]);
                let nodes = a.pool(1, 0x140)[0];
                for k in 0..75 {
                    put(nodes, k * 4, coord(rng));
                }
                let count = match rng.below(10) {
                    0 => 1,
                    1 => 0x1A,
                    2 => 0,
                    3 => 0xFFFF_FFFF,
                    4 => 0x19,
                    5 => 2,
                    _ => 2 + rng.below(23),
                };
                let b = |rng: &mut Rng| match rng.below(4) {
                    0 => 0,
                    1 => 1,
                    2 => rng.u32() & 0xFFFF_FF00,
                    _ => rng.u32(),
                };
                let a8 = match rng.below(5) {
                    0 => (-1.0f32).to_bits(),
                    1 => 0x7FC0_0000,
                    2 => 0,
                    _ => coord(rng),
                };
                let ar = args(&[veh, count, b(rng), b(rng), b(rng), b(rng), b(rng), a8, rng.u32()]);
                (
                    regs(rng.u32(), nodes, rng.u32(), ESI0, EDI0),
                    ar,
                    Cmp { eax_mask: u32::MAX, st0: false, pop: 0, preserved: SAVED, same: 0 },
                )
            },
            "nodes",
        );
    }
}

#[cfg(test)]
mod tests_f {
    use super::tc::*;

    const GOAL_FIELDS: &[(usize, usize)] = &[(0, 1), (4, 12), (0x10, 4), (0x18, 4), (0x24, 1), (0x28, 12)];

    #[test]
    #[ignore = "needs the test exe linked at /BASE:0x10000000 (see the kit comment)"]
    fn to_matches_original() {
        let _g = lock();
        let mut cookie = callee(0xC9604F, 0, 0, 0, Ret::Keep, Fx::None);
        cookie.silent = true;
        let callees = vec![
            callee(OWNED_LOCALLY, 0, 0, EAX, Ret::Bool, Fx::None),
            { let mut c = callee(FIND_CONN, 0, 0, EAX | EDX, Ret::Any, Fx::None); c.byte_regs = EDX; c },
            callee(NET_SEND, 4, 0, ESI, Ret::Any, Fx::LogBuf),
            callee(OWNED_ROUTE_FN, 0, 0, ECX, Ret::Ptr(1), Fx::None),
            callee(NEAREST_LANE_MASK_ADDR, 0, 0, EAX, Ret::Any, Fx::None),
            callee(LANE_CLASS, 0, 0, EAX, Ret::Bool, Fx::None),
            callee(FIND_LANE, 0, 0, EAX, Ret::Ptr(1), Fx::LogEaxMem(&[(0, 4), (4, 4), (8, 4), (0xC, 4), (0x10, 4), (0x18, 2)])),
            callee(ROUTE_POS_OK, 0, 0, EAX | EDX, Ret::Bool, Fx::None),
            callee(CLOSEST_LANE_FN, 2, 0, ECX | EDX, Ret::Ptr(1), Fx::None),
            callee(SPLINE_EVAL_POS, 1, 4, EAX | ESI, Ret::Any, Fx::Out3Esi),
            callee(ROUTE_BUILD_B, 2, 0, 0, Ret::Ptr(0), Fx::RouteBlock),
            callee(SPLINE_CLOSEST, 0, 0, EAX | ESI | EDI, Ret::St0, Fx::Out3Esi),
            callee(ORDER_0D, 2, 0, ECX, Ret::Any, Fx::None),
            callee(ORDER_09, 1, 0, ECX | ESI, Ret::Any, Fx::None),
            callee(ROUTE_TAIL_FN, 3, 0, EDI, Ret::Any, Fx::None),
            callee(GOAL_INSTALL, 3, 0, EAX | ECX, Ret::Any, Fx::LogEaxMem(GOAL_FIELDS)),
            cookie,
        ];
        let h = Harness::new(
            0xB27830,
            &TO_BODY,
            &TO_BODY_CALLS,
            &TO_BODY_DISPS,
            callees,
            &[(0xE38AE0, 4), (0xE8725C, 4), (OBJ_POOL, 0x1_0000), (LANE_QUERY_F, 4), (HALF_F, 4), (CLOSEST_LANE_F, 4)],
            to_thunk as *const () as usize,
        );
        run_cases(
            &h,
            cases(),
            |h, rng| unsafe {
                h.mem.fill_random(rng);
                for (va, n) in [(0xE38AE0usize, 4usize), (0xE8725C, 4), (LANE_QUERY_F, 4), (HALF_F, 4), (CLOSEST_LANE_F, 4)] {
                    put_const(va, n);
                }
                let mut a = Arena::new();
                let veh = a.pool(1, 0x9000)[0];
                let obj = a.pool(1, 0x100)[0];
                let blk = a.pool(1, 0x10)[0];
                let hnd = (1 + rng.below(0xFF)) << 12 | (1 + rng.below(4000));
                put(veh, 0x44, if rng.one_in(6) { 0 } else { hnd });
                wd(OBJ_POOL + (((hnd & 0xFFF) as usize) << 4), if rng.one_in(5) { 0 } else { obj });
                put(obj, 0x44, if rng.one_in(6) { rng.u32() } else { hnd });
                put(obj, 0xB0, if rng.one_in(5) { 0 } else { blk });
                putb(blk, 0, rng.u32() as u8);
                *((blk as usize + 2) as *mut u16) = rng.pick(&[0xFFFFu16, 5, 0x1234, 0]);
                put(veh, 0xB0, if rng.one_in(4) { 0 } else { blk });
                putb(veh, 0x8566, rng.u32() as u8);
                for q in 0..3 {
                    put(veh, 0x14 + 4 * q, coord(rng));
                }
                wb(NET_EXTRA_BYTE, rng.below(2) as u8);
                wd(NET_SESSION, rng.u32());
                wd(0x2528C14, rng.u32());
                let lanes = a.pool(2, 0x40);
                let routes = a.pool(3, 0x40);
                let rblk = a.pool(3, 0x40);
                for (i, &r) in routes.iter().enumerate() {
                    put(r, 4, rblk[i]);
                    put(rblk[i], 0xC, rng.u32());
                    put(r, 0xC, rng.u32());
                }
                set_pools(vec![routes.clone(), lanes.clone()]);
                let nodes = a.pool(1, 0x140)[0];
                for k in 0..75 {
                    put(nodes, k * 4, coord(rng));
                }
                let count = match rng.below(10) {
                    0 => 1,
                    1 => 0x1A,
                    2 => 0,
                    3 => 3,
                    4 => 0x19,
                    5 => 2,
                    _ => 2 + rng.below(23),
                };
                let b = |rng: &mut Rng| match rng.below(4) {
                    0 => 0,
                    1 => 1,
                    2 => rng.u32() & 0xFFFF_FF00,
                    _ => rng.u32(),
                };
                let a8 = match rng.below(5) {
                    0 => (-1.0f32).to_bits(),
                    1 => 0x7FC0_0000,
                    2 => 0,
                    _ => coord(rng),
                };
                let ar = args(&[nodes, count, b(rng), b(rng), b(rng), a8, rng.u32()]);
                (
                    regs(rng.u32(), veh, rng.u32(), ESI0, EDI0),
                    ar,
                    Cmp { eax_mask: u32::MAX, st0: false, pop: 0, preserved: SAVED, same: 0 },
                )
            },
            "to",
        );
    }
}
